-- ==== Util ===============================================
__define("Util", (function()
--[[
	AOTR Suite :: Util
	Low level helpers shared by every module.

	Nothing in here knows about Attack on Titan: Revolution specifically.
	It only knows how to talk to Roblox, the executor, and the filesystem.
]]

return function(Ctx)
	local Util = {}

	local Players = game:GetService("Players")
	local HttpService = game:GetService("HttpService")
	local RunService = game:GetService("RunService")
	local VirtualInputManager = game:GetService("VirtualInputManager")

	------------------------------------------------------------------
	-- Executor capability detection
	------------------------------------------------------------------

	Util.requestFunc = (syn and syn.request)
		or (fluxus and fluxus.request)
		or (http and http.request)
		or (krnl and krnl.request)
		or (delta and delta.request)
		or http_request
		or request

	Util.hasFileIO = (type(writefile) == "function" and type(readfile) == "function")
	Util.hasMakeFolder = type(makefolder) == "function"
	Util.hasIsFile = type(isfile) == "function"
	Util.hasListFiles = type(listfiles) == "function"
	Util.hasDeleteFile = type(delfile) == "function"

	Util.getGuiHost = function()
		local ok, host = pcall(function()
			return (gethui and gethui()) or game:GetService("CoreGui")
		end)
		if ok and host then
			return host
		end
		return game:GetService("CoreGui")
	end

	------------------------------------------------------------------
	-- Logging
	------------------------------------------------------------------

	local LOG_PREFIX = "[AOTR] "

	Util.log = function(...)
		local parts = {}
		for i = 1, select("#", ...) do
			parts[#parts + 1] = tostring((select(i, ...)))
		end
		print(LOG_PREFIX .. table.concat(parts, " "))
	end

	Util.warn = function(...)
		local parts = {}
		for i = 1, select("#", ...) do
			parts[#parts + 1] = tostring((select(i, ...)))
		end
		warn(LOG_PREFIX .. table.concat(parts, " "))
	end

	------------------------------------------------------------------
	-- Misc helpers
	------------------------------------------------------------------

	Util.clamp = function(value, low, high)
		if type(value) ~= "number" then
			return low
		end
		if value < low then
			return low
		end
		if value > high then
			return high
		end
		return value
	end

	-- pcall that returns (ok, result...) and never throws
	Util.try = function(fn, ...)
		if type(fn) ~= "function" then
			return false
		end
		local packed = table.pack(pcall(fn, ...))
		return table.unpack(packed, 1, packed.n)
	end

	-- pcall that swallows errors and returns the result (or nil)
	Util.safe = function(fn, ...)
		local ok, result = pcall(fn, ...)
		if ok then
			return result
		end
		return nil
	end

	Util.now = function()
		return os.clock()
	end

	Util.deepCopy = function(value)
		if type(value) ~= "table" then
			return value
		end
		local copy = {}
		for key, item in pairs(value) do
			copy[key] = Util.deepCopy(item)
		end
		return copy
	end

	-- Recursive merge: `override` wins, tables are merged key by key.
	Util.deepMerge = function(base, override)
		if type(override) ~= "table" then
			if override ~= nil then
				return override
			end
			return base
		end
		if type(base) ~= "table" then
			return Util.deepCopy(override)
		end
		local result = Util.deepCopy(base)
		for key, item in pairs(override) do
			if type(item) == "table" and type(result[key]) == "table" then
				result[key] = Util.deepMerge(result[key], item)
			else
				result[key] = Util.deepCopy(item)
			end
		end
		return result
	end

	Util.formatNumber = function(value)
		if type(value) ~= "number" then
			return tostring(value)
		end
		local absolute = math.abs(value)
		if absolute >= 1e12 then
			return string.format("%.2fT", value / 1e12)
		elseif absolute >= 1e9 then
			return string.format("%.2fB", value / 1e9)
		elseif absolute >= 1e6 then
			return string.format("%.2fM", value / 1e6)
		elseif absolute >= 1e3 then
			return string.format("%.1fK", value / 1e3)
		end
		return string.format("%d", value)
	end

	Util.formatDuration = function(seconds)
		if type(seconds) ~= "number" or seconds < 0 then
			return "00:00"
		end
		local total = math.floor(seconds)
		local hours = math.floor(total / 3600)
		local minutes = math.floor((total % 3600) / 60)
		local secs = total % 60
		if hours > 0 then
			return string.format("%02d:%02d:%02d", hours, minutes, secs)
		end
		return string.format("%02d:%02d", minutes, secs)
	end

	-- File-system safe profile name.
	Util.sanitizeName = function(name)
		name = tostring(name or "")
		name = name:gsub("[^%w%-_%. ]", "")
		name = name:gsub("^%s+", ""):gsub("%s+$", "")
		if #name == 0 then
			return "default"
		end
		if #name > 48 then
			name = name:sub(1, 48)
		end
		return name
	end

	------------------------------------------------------------------
	-- Instance traversal
	------------------------------------------------------------------

	Util.waitFor = function(parent, name, timeout)
		if not parent then
			return nil
		end
		local found = parent:FindFirstChild(name)
		if found then
			return found
		end
		if timeout == nil then
			return nil
		end
		local ok, result = pcall(function()
			return parent:WaitForChild(name, timeout)
		end)
		if ok then
			return result
		end
		return nil
	end

	-- Depth limited deep search for the first matching descendant.
	Util.findDeep = function(root, predicate, maxDepth)
		maxDepth = maxDepth or 8
		if not root then
			return nil
		end
		local queue = { { root, 0 } }
		while #queue > 0 do
			local entry = table.remove(queue, 1)
			local node, depth = entry[1], entry[2]
			if node and depth <= maxDepth then
				if predicate(node) then
					return node
				end
				for _, child in ipairs(node:GetChildren()) do
					table.insert(queue, { child, depth + 1 })
				end
			end
		end
		return nil
	end

	Util.findAllDeep = function(root, predicate, maxDepth)
		maxDepth = maxDepth or 8
		local results = {}
		if not root then
			return results
		end
		local queue = { { root, 0 } }
		while #queue > 0 do
			local entry = table.remove(queue, 1)
			local node, depth = entry[1], entry[2]
			if node and depth <= maxDepth then
				if predicate(node) then
					table.insert(results, node)
				end
				for _, child in ipairs(node:GetChildren()) do
					table.insert(queue, { child, depth + 1 })
				end
			end
		end
		return results
	end

	-- True when the instance and every GuiObject ancestor is visible.
	Util.isVisible = function(object)
		if not object or not object:IsA("GuiObject") then
			return false
		end
		local current = object
		while current and current:IsA("GuiObject") do
			if not current.Visible then
				return false
			end
			current = current.Parent
		end
		local screen = object:FindFirstAncestorOfClass("ScreenGui")
		if screen and not screen.Enabled then
			return false
		end
		return object.AbsoluteSize.X > 0 and object.AbsoluteSize.Y > 0
	end

	------------------------------------------------------------------
	-- Input simulation
	------------------------------------------------------------------

	-- VirtualInputManager clicks are offset because Roblox reports the
	-- viewport in a different space than the mouse. 58-65 works for the
	-- standard 16:9 and 16:10 Roblox window chrome.
	Util.CLICK_Y_OFFSET = 58

	Util.click = function(object, yOffset)
		if not object or not object:IsA("GuiObject") then
			return false
		end
		local x = object.AbsolutePosition.X + (object.AbsoluteSize.X / 2)
		local y = object.AbsolutePosition.Y + (object.AbsoluteSize.Y / 2) + (yOffset or Util.CLICK_Y_OFFSET)
		pcall(function()
			VirtualInputManager:SendMouseButtonEvent(x, y, 0, true, game, 1)
		end)
		task.wait(0.04)
		pcall(function()
			VirtualInputManager:SendMouseButtonEvent(x, y, 0, false, game, 1)
		end)
		return true
	end

	Util.pressKey = function(keyCode, holdTime)
		holdTime = holdTime or 0.05
		pcall(function()
			VirtualInputManager:SendKeyEvent(true, keyCode, false, game)
		end)
		task.wait(holdTime)
		pcall(function()
			VirtualInputManager:SendKeyEvent(false, keyCode, false, game)
		end)
	end

	-- Sends a left mouse click at the current mouse position. The game
	-- listens to the mouse for the blade swings, so the attack has to be
	-- simulated as well.
	Util.pressMouse = function()
		pcall(function()
			VirtualInputManager:SendMouseButtonEvent(0, 0, 0, true, game, 1)
		end)
		task.wait(0.01)
		pcall(function()
			VirtualInputManager:SendMouseButtonEvent(0, 0, 0, false, game, 1)
		end)
	end

	------------------------------------------------------------------
	-- HTTP
	------------------------------------------------------------------

	Util.httpRequest = function(options)
		if not Util.requestFunc then
			return nil
		end
		local ok, response = pcall(Util.requestFunc, options)
		if not ok or type(response) ~= "table" then
			return nil
		end
		return response
	end

	Util.jsonEncode = function(value)
		local ok, encoded = pcall(function()
			return HttpService:JSONEncode(value)
		end)
		if ok then
			return encoded
		end
		return nil
	end

	Util.jsonDecode = function(text)
		local ok, decoded = pcall(function()
			return HttpService:JSONDecode(text)
		end)
		if ok then
			return decoded
		end
		return nil
	end

	------------------------------------------------------------------
	-- Services exposed for convenience
	------------------------------------------------------------------

	Util.Players = Players
	Util.RunService = RunService
	Util.LocalPlayer = Players.LocalPlayer

	-- Re-acquire the local player after a respawn / rejoin.
	Util.refreshLocalPlayer = function()
		Util.LocalPlayer = Players.LocalPlayer
		return Util.LocalPlayer
	end

	-- Small helper: run a function on a cadence and never overlap calls.
	Util.createLooper = function(interval, fn)
		local running = false
		return function()
			if running then
				return
			end
			running = true
			task.spawn(function()
				while true do
					local ok, err = pcall(fn)
					if not ok then
						Util.warn("loop error:", err)
					end
					task.wait(interval)
				end
			end)
		end
	end

	return Util
end

end)())

-- ==== Config ===============================================
__define("Config", (function()
--[[
	AOTR Suite :: Config
	Schema + multi profile configuration store.

	Design notes
	------------
	* The schema is intentionally a superset of the classic `TekkitConfig`
	  table, so configs written for Tekkit Hub keep loading unchanged.
	* Profiles are stored one file per profile under a single folder:
	      AOTRSuite/configs/<profile>.json
	  and the active profile name lives in
	      AOTRSuite/active.txt
	  This fixes the "unorganized / duplicated config files" problem.
	* Every write goes through an atomic temp-file swap and a single flight
	  guard, which fixes the race condition on file loading.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Config = {}

	------------------------------------------------------------------
	-- Schema
	------------------------------------------------------------------

	Config.ROOT_FOLDER = "AOTRSuite"
	Config.CONFIG_FOLDER = "AOTRSuite/configs"
	Config.ACTIVE_FILE = "AOTRSuite/active.txt"
	Config.DEFAULT_PROFILE = "default"

	Config.DEFAULTS = {
		-- ===== FARM =====
		AutoFarm = false,
		FarmMethod = "Blade", -- "Blade" | "Hover" | "Teleport"
		DisableHovering = false,
		TargetPriority = "Closest", -- "Closest" | "Bosses First" | "Crawlers & Abnormals" | "Lowest HP"
		HoverHeight = 265,
		HoverSpeed = 3000,
		BehindNapeDistance = 2,
		TeleportTitans = false,
		HitDistance = 1000,
		MultiHit = 9,
		BossDamage = 9,
		DamageExtender = false,
		DamageMultiplier = 3,
		InfiniteSpears = false,
		NapeExtend = false,
		TitanEsp = false,
		NoTitanLag = true,
		DisableRendering = true,
		AutoUseSkills = false,

		-- ===== RELOAD / REFILL =====
		AutoReload = false,
		AutoRefill = false,
		ReloadStation = "Safest", -- "Safest" | "Nearest"
		SafetyTime = 30, -- hard minimum is 30 seconds

		-- ===== CLAIMS =====
		ClaimAchievements = false,
		ClaimQuests = false,
		ClaimBattlePass = true,
		-- ClaimDailyReward has no toggle on purpose, it is always active.

		-- ===== BOOSTS =====
		BuyBoosts = false,
		ItemtoBuyWith = "Canes", -- "Canes" | "Gems" | "Pumpkins"
		Boosts = { "2x Gold Boost [2h]" },

		-- ===== AUTO START =====
		AutoStart = false,
		AutoStartType = "Missions", -- "Missions" | "Raids"
		AutoStartMap = "Shiganshina",
		AutoStartObjective = "Breach",
		AutoStartDifficulty = "Hardest (w/ Freedom)",
		AutoStartModifiers = {
			"No Skills",
			"No Talents",
			"Nightmare",
			"Oddball",
			"Injury Prone",
			"Chronic Injuries",
			"Fog",
			"Glass Cannon",
			"Time Trial",
		},
		PlayBoostedMap = false,
		AutoReturn = false,
		ReturnAmount = 15,
		Kaitun = false,

		-- ===== WAVES =====
		WaveToDieAt = 0,
		AutoWaveDie = false,
		WavesRollBlessing = false,
		WavesBuyUpgrades = false,
		WavesAutoUpgrade = false,
		WavesAutoSkip = false,
		WavesGetCrates = false,
		WavesUpgradesToBuy = {},
		TargetBoss = false,

		-- ===== PROGRESSION =====
		AutoPrestige = false,
		PrestigeToStopAt = 5,
		AutoSkillTree = false,
		LeftPath = "Skill Cooldown",
		MiddlePath = "Damage",
		RightPath = "Damage Reduction",
		PathPriority = "Middle",

		-- ===== WEBHOOK =====
		Webhook = false,
		WebhookLink = "",
		ShowUsername = true,
		SendSafetyUpdate = false,

		-- ===== MISC =====
		AntiAFK = true,
		ShadowBanCheck = false,
		PrivateServerCode = "-",
		LeaveIfMorePlayers = false,
		AutoSelectSlot = true,
		Slot = "B",
		StreakAmount = 0,
		StreakDie = false,

		-- ===== PROFILE =====
		ConfigProfile = Config.DEFAULT_PROFILE,
	}

	-- Difficulty ladder used by Auto Start. "Hardest (w/ Freedom)" is the
	-- top tier that is only selectable once Freedom is unlocked.
	Config.DIFFICULTIES = {
		{ name = "Easy", grade = 2 },
		{ name = "Normal", grade = 5 },
		{ name = "Hard", grade = 8 },
		{ name = "Severe", grade = 11 },
		{ name = "Aberrant", grade = 14 },
		{ name = "Freedom", grade = 15 },
		{ name = "Hardest (w/ Freedom)", grade = 15 },
	}

	Config.CURRENCIES = { "Canes", "Gems", "Pumpkins" }

	------------------------------------------------------------------
	-- Current state
	------------------------------------------------------------------

	Config.Data = Util.deepCopy(Config.DEFAULTS)
	Config.ActiveProfile = Config.DEFAULT_PROFILE

	------------------------------------------------------------------
	-- Filesystem helpers
	------------------------------------------------------------------

	local function ensureFolder(path)
		if not Util.hasMakeFolder then
			return
		end
		-- Walk the path and create every segment. Most executors create
		-- parents automatically, but a few do not.
		local parts = {}
		for segment in string.gmatch(path, "[^/\\]+") do
			parts[#parts + 1] = segment
		end
		local current = ""
		for _, segment in ipairs(parts) do
			current = current .. "/" .. segment
			pcall(makefolder, current)
		end
	end

	local function writeAtomic(path, content)
		if not Util.hasFileIO then
			return false
		end
		ensureFolder(Config.CONFIG_FOLDER)
		local temp = path .. ".tmp"
		local ok = pcall(function()
			writefile(temp, content)
		end)
		if not ok then
			return false
		end
		local data = Util.safe(readfile, temp)
		if data == nil then
			pcall(function()
				delfile(temp)
			end)
			return false
		end
		pcall(function()
			writefile(path, data)
		end)
		pcall(function()
			delfile(temp)
		end)
		return true
	end

	local function removeFile(path)
		if Util.hasDeleteFile then
			pcall(delfile, path)
		end
	end

	------------------------------------------------------------------
	-- Profile discovery
	------------------------------------------------------------------

	-- Profiles are compared by a normalised key, so "Farm One",
	-- "farm one" and "FarmOne" are the same profile and never end up as
	-- three separate files.
	local function profileKey(name)
		local key = string.lower(Util.sanitizeName(name))
		key = key:gsub("[%s%-]", "")
		return key
	end

	-- Lists profiles without duplicates. Files whose names only differ by
	-- case are treated as the same profile, which removes the duplicated
	-- config files that older versions produced.
	Config.listProfiles = function()
		local profiles = {}
		local seen = {}
		if not Util.hasFileIO then
			return profiles
		end
		ensureFolder(Config.CONFIG_FOLDER)
		local files = {}
		if Util.hasListFiles then
			local ok, list = pcall(listfiles, Config.CONFIG_FOLDER)
			if ok and type(list) == "table" then
				files = list
			end
		end
		if #files == 0 and Util.hasIsFile then
			-- Fall back to the known profiles we may have written before.
			for _, name in ipairs({ Config.DEFAULT_PROFILE, Config.ActiveProfile }) do
				local file = Config.CONFIG_FOLDER .. "/" .. Util.sanitizeName(name) .. ".json"
				if Util.safe(isfile, file) then
					table.insert(files, file)
				end
			end
		end
		for _, file in ipairs(files) do
			if type(file) == "string" and file:match("%.json$") then
				local base = file:match("([^/\\]+)%.json$")
				local key = profileKey(base)
				if key ~= "" and not seen[key] then
					seen[key] = true
					table.insert(profiles, { name = base, file = file, key = key })
				end
			end
		end
		table.sort(profiles, function(a, b)
			return a.key < b.key
		end)
		return profiles
	end

	Config.profilePath = function(name)
		return Config.CONFIG_FOLDER .. "/" .. Util.sanitizeName(name) .. ".json"
	end

	------------------------------------------------------------------
	-- Load / save with single flight guard
	------------------------------------------------------------------

	-- Any load that starts while another one is running is queued instead
	-- of racing it. Combined with the generation counter this removes the
	-- race condition on file loading entirely.
	local loadGeneration = 0
	local loadInProgress = false
	local loadWaiters = {}

	local function releaseLoad()
		loadInProgress = false
		local waiters = loadWaiters
		loadWaiters = {}
		for _, waiter in ipairs(waiters) do
			waiter()
		end
	end

	local function rawLoad(name)
		local file = Config.profilePath(name)
		if not Util.hasFileIO then
			return false
		end
		if Util.hasIsFile and not Util.safe(isfile, file) then
			return false
		end
		local raw = Util.safe(readfile, file)
		if type(raw) ~= "string" or raw == "" then
			return false
		end
		local decoded = Util.jsonDecode(raw)
		if type(decoded) ~= "table" then
			return false
		end
		Config.Data = Util.deepMerge(Config.DEFAULTS, decoded)
		Config.Data.ConfigProfile = Util.sanitizeName(name)
		Config.ActiveProfile = Config.Data.ConfigProfile
		return true
	end

	Config.loadProfile = function(name)
		name = Util.sanitizeName(name or Config.ActiveProfile)
		if loadInProgress then
			-- Queue behind the running load instead of starting a second one.
			local waiter
			waiter = function()
				Config.loadProfile(name)
			end
			table.insert(loadWaiters, waiter)
			return false
		end
		loadInProgress = true
		loadGeneration = loadGeneration + 1
		local generation = loadGeneration
		local ok = false
		ok = rawLoad(name)
		if generation ~= loadGeneration then
			-- A newer load superseded this one, drop the result.
			releaseLoad()
			return false
		end
		if ok then
			Config.writeActiveProfile(name)
			Config.notifyChanged()
		end
		releaseLoad()
		return ok
	end

	Config.writeActiveProfile = function(name)
		if not Util.hasFileIO then
			return
		end
		ensureFolder(Config.ROOT_FOLDER)
		writeAtomic(Config.ACTIVE_FILE, Util.sanitizeName(name))
	end

	Config.readActiveProfile = function()
		if not Util.hasFileIO then
			return nil
		end
		local raw = Util.safe(readfile, Config.ACTIVE_FILE)
		if type(raw) ~= "string" or raw == "" then
			return nil
		end
		return Util.sanitizeName(raw)
	end

	------------------------------------------------------------------
	-- Public API
	------------------------------------------------------------------

	Config.Save = function(name)
		name = Util.sanitizeName(name or Config.ActiveProfile)
		Config.Data.ConfigProfile = name
		Config.ActiveProfile = name
		if not Util.hasFileIO then
			return false
		end
		ensureFolder(Config.CONFIG_FOLDER)
		local ok = writeAtomic(Config.profilePath(name), Util.jsonEncode(Config.Data) or "")
		if ok then
			Config.writeActiveProfile(name)
			-- Remove any older duplicate that maps to the same profile key.
			local key = profileKey(name)
			for _, profile in ipairs(Config.listProfiles()) do
				if profile.key == key and profile.name ~= Util.sanitizeName(name) then
					removeFile(profile.file)
				end
			end
		end
		return ok
	end

	Config.New = function(name)
		name = Util.sanitizeName(name)
		Config.Data = Util.deepCopy(Config.DEFAULTS)
		Config.Data.ConfigProfile = name
		Config.ActiveProfile = name
		return Config.Save(name)
	end

	Config.Delete = function(name)
		name = Util.sanitizeName(name)
		removeFile(Config.profilePath(name))
		if profileKey(name) == profileKey(Config.ActiveProfile) then
			Config.ActiveProfile = Config.DEFAULT_PROFILE
			Config.Data = Util.deepCopy(Config.DEFAULTS)
			Config.writeActiveProfile(Config.DEFAULT_PROFILE)
		end
		return true
	end

	Config.Select = function(name)
		name = Util.sanitizeName(name)
		if not Config.loadProfile(name) then
			-- Selecting a profile that does not exist yet creates it.
			Config.New(name)
		end
		return Config.ActiveProfile
	end

	------------------------------------------------------------------
	-- Change notification (used by the Config tab to mark it dirty)
	------------------------------------------------------------------

	local changeListeners = {}

	Config.onChanged = function(callback)
		table.insert(changeListeners, callback)
	end

	Config.notifyChanged = function()
		for _, callback in ipairs(changeListeners) do
			pcall(callback)
		end
	end

	Config.Get = function()
		return Config.Data
	end

	-- Dotted path setter: Config.Set("Farm.HoverHeight", 300)
	Config.Set = function(path, value)
		local segments = {}
		for segment in string.gmatch(tostring(path), "[^%.]+") do
			table.insert(segments, segment)
		end
		if #segments == 0 then
			return
		end
		local node = Config.Data
		for index = 1, #segments - 1 do
			local key = segments[index]
			if type(node[key]) ~= "table" then
				node[key] = {}
			end
			node = node[key]
		end
		node[segments[#segments]] = value
		Config.notifyChanged()
	end

	------------------------------------------------------------------
	-- Boot: auto load
	------------------------------------------------------------------

	-- Auto Load Config:
	--   1. start from the defaults
	--   2. overlay a `TekkitConfig` table if the user exported one
	--   3. overlay the profile that was active last time
	Config.AutoLoad = function()
		Config.Data = Util.deepCopy(Config.DEFAULTS)

		local genv = (getgenv and getgenv()) or _G
		local tekkit = genv.TekkitConfig
		if type(tekkit) == "table" then
			Config.Data = Util.deepMerge(Config.Data, tekkit)
			Util.log("merged external TekkitConfig")
		end

		local active = Config.readActiveProfile()
		if active then
			if Config.loadProfile(active) then
				Util.log("auto loaded config profile:", active)
			end
		end

		if not Util.hasFileIO then
			Util.warn("executor has no file access, config persistence is disabled")
		end
		return Config.Data
	end

	return Config
end

end)())

-- ==== Remotes ===============================================
__define("Remotes", (function()
--[[
	AOTR Suite :: Remotes
	Thin wrapper around the Attack on Titan: Revolution server API.

	The game exposes a single action dispatcher:

		ReplicatedStorage.Assets.Remotes.POST   (RemoteEvent)
		ReplicatedStorage.Assets.Remotes.GET    (RemoteEvent / RemoteFunction)

	`POST:FireServer(<Category>, <Action>, ...)` performs the action.
	Categories observed in the live game:
		S_Equipment / Equipment / Character / Attacks / Hitboxes
	]]

return function(Ctx)
	local Util = Ctx.Util
	local Remotes = {}

	local ReplicatedStorage = game:GetService("ReplicatedStorage")

	local postRemote = nil
	local getRemote = nil
	local resolvedAt = 0

	------------------------------------------------------------------
	-- Resolution
	------------------------------------------------------------------

	local function findRemote(name)
		local candidates = {
			ReplicatedStorage:FindFirstChild("Assets") and ReplicatedStorage.Assets:FindFirstChild("Remotes"),
			ReplicatedStorage:FindFirstChild("Remotes"),
		}
		for _, container in ipairs(candidates) do
			if container then
				local direct = container:FindFirstChild(name)
				if direct then
					return direct
				end
			end
		end
		-- Deep fallback: the game occasionally nests the remotes deeper.
		return Util.findDeep(ReplicatedStorage, function(node)
			return node.Name == name and (node:IsA("RemoteEvent") or node:IsA("RemoteFunction"))
		end, 6)
	end

	Remotes.resolve = function(force)
		if not force and postRemote and (Util.now() - resolvedAt) < 30 then
			return postRemote, getRemote
		end
		postRemote = findRemote("POST")
		getRemote = findRemote("GET")
		resolvedAt = Util.now()
		return postRemote, getRemote
	end

	Remotes.post = function(...)
		local remote = Remotes.resolve()
		if not remote then
			return false
		end
		local args = table.pack(...)
		return pcall(function()
			remote:FireServer(table.unpack(args, 1, args.n))
		end)
	end

	Remotes.invoke = function(...)
		local remote = Remotes.resolve()
		if not remote then
			return nil
		end
		local args = table.pack(...)
		if remote:IsA("RemoteFunction") then
			local ok, result = pcall(function()
				return remote:InvokeServer(table.unpack(args, 1, args.n))
			end)
			if ok then
				return result
			end
			return nil
		end
		Remotes.post(table.unpack(args, 1, args.n))
		return nil
	end

	------------------------------------------------------------------
	-- Action learning
	------------------------------------------------------------------
	-- The game occasionally renames a category. Instead of hard failing we
	-- remember which spelling worked the last time and try it first.

	local learned = {}

	Remotes.remember = function(feature, action)
		learned[feature] = action
	end

	Remotes.recall = function(feature)
		return learned[feature]
	end

	-- Fires the first candidate signature that does not error.
	-- `candidates` is a list of tables, each table being the argument list.
	Remotes.postAny = function(feature, candidates)
		local remembered = learned[feature]
		if remembered then
			for index, candidate in ipairs(candidates) do
				if candidate[1] == remembered[1] then
					table.remove(candidates, index)
					table.insert(candidates, 1, remembered)
					break
				end
			end
		end
		for _, candidate in ipairs(candidates) do
			local ok = Remotes.post(table.unpack(candidate))
			if ok then
				learned[feature] = candidate
				return true, candidate
			end
		end
		return false
	end

	------------------------------------------------------------------
	-- High level actions used across the suite
	------------------------------------------------------------------

	Remotes.refill = function()
		Remotes.post("S_Equipment", "Refill")
		Remotes.post("Equipment", "Refill")
		Remotes.post("Character", "Refill")
		Remotes.post("Attacks", "Refill")
	end

	-- Registers a hitbox for a server side damage check.
	-- `damage` and `critical` mirror the arguments the game expects.
	Remotes.registerHitbox = function(part, damage, critical)
		if not part or not part.Parent then
			return false
		end
		Remotes.post("Hitboxes", "Register", part, damage or 500, critical or 100)
		return true
	end

	Remotes.slash = function()
		Remotes.post("Attacks", "Slash", true)
		Remotes.post("Attacks", "Slash_Release")
		Remotes.post("Attacks", "M1")
	end

	Remotes.fireSpears = function(position)
		if not position then
			return false
		end
		Remotes.post("S_Equipment", "Spears", "Fire", position)
		Remotes.post("Attacks", "Spears", position)
		return true
	end

	Remotes.getReady = function()
		return getRemote
	end

	return Remotes
end

end)())

-- ==== GameUI ===============================================
__define("GameUI", (function()
--[[
	AOTR Suite :: GameUI
	Everything that touches the game's own interface.

	Verified layout of Attack on Titan: Revolution (place 13379208636 / 14916516914):

		PlayerGui.Interface
		  .Title_Screen
		    .Slots.A.Select_A
		    .Buttons.Play
		  .Warning.Prompt.Main.No
		  .Missions
		    .Prompt.Selection.Missions
		    .Missions.Main.Maps.Maps.<Map>_Missions
		    .Missions.Main.Info.Main.Buttons.Creation_Missions
		    .Info.Main.Info.Modifiers.Modifiers_Buttons
		    .Info.Main.Info.Modifiers.Options.<Modifier>
		    .Info.Main.Info.Main.Info_Buttons.Begin
		  .Rewards
		    .Main.Info.Main.Buttons.Retry
		    .Main.Info.Main.Buttons.Leave_2
		  .HUD.Main.Top["7"].Blades.Inner.Bar.Gradient
		  .HUD.Main.Top["7"].Gas.Inner.Bar.Gradient

	Paths change between game updates, so every lookup has a keyword based
	fallback that searches the interface tree instead of trusting a path.
]]

return function(Ctx)
	local Util = Ctx.Util
	local GameUI = {}

	local Players = game:GetService("Players")

	local function playerGui()
		local player = Util.LocalPlayer or Players.LocalPlayer
		if not player then
			return nil
		end
		return player:FindFirstChildOfClass("PlayerGui")
	end

	------------------------------------------------------------------
	-- Core lookups
	------------------------------------------------------------------

	GameUI.interface = function()
		local gui = playerGui()
		if not gui then
			return nil
		end
		return gui:FindFirstChild("Interface") or gui
	end

	GameUI.find = function(path)
		local root = GameUI.interface()
		if not root then
			return nil
		end
		local node = root
		for segment in string.gmatch(path, "[^%.]+") do
			node = node:FindFirstChild(segment)
			if not node then
				return nil
			end
		end
		return node
	end

	GameUI.missions = function()
		return GameUI.find("Missions")
	end

	GameUI.rewards = function()
		return GameUI.find("Rewards")
	end

	GameUI.hud = function()
		return GameUI.find("HUD")
	end

	GameUI.titleScreen = function()
		return GameUI.find("Title_Screen")
	end

	------------------------------------------------------------------
	-- Keyword driven search
	------------------------------------------------------------------

	local CLICKABLE = { "TextButton", "ImageButton" }

	local function labelOf(object)
		local text = ""
		if object:IsA("TextLabel") or object:IsA("TextButton") then
			text = object.Text or ""
		elseif object:IsA("ImageButton") or object:IsA("ImageLabel") then
			text = object.ImageLabel and object.ImageLabel.Text or ""
		end
		return (text .. " " .. object.Name):lower()
	end

	-- Finds clickable elements whose text or name contains any keyword.
	GameUI.findClickables = function(root, keywords, requireVisible)
		local results = {}
		root = root or GameUI.interface()
		if not root then
			return results
		end
		if type(keywords) == "string" then
			keywords = { keywords }
		end
		local lowered = {}
		for index, keyword in ipairs(keywords) do
			lowered[index] = string.lower(tostring(keyword))
		end
		local candidates = Util.findAllDeep(root, function(node)
			for _, class in ipairs(CLICKABLE) do
				if node:IsA(class) then
					return true
				end
			end
			return false
		end, 12)
		for _, node in ipairs(candidates) do
			local label = labelOf(node)
			for _, keyword in ipairs(lowered) do
				if keyword ~= "" and string.find(label, keyword, 1, true) then
					if not requireVisible or Util.isVisible(node) then
						table.insert(results, node)
					end
					break
				end
			end
		end
		return results
	end

	GameUI.clickFirst = function(root, keywords, requireVisible)
		local matches = GameUI.findClickables(root, keywords, requireVisible)
		if #matches == 0 then
			return false
		end
		return Util.click(matches[1])
	end

	-- Opens a top level menu of the interface by its name.
	GameUI.openMenu = function(name)
		local matches = GameUI.findClickables(GameUI.interface(), { name }, true)
		if #matches == 0 then
			return false
		end
		Util.click(matches[1])
		return true
	end

	------------------------------------------------------------------
	-- HUD readouts
	------------------------------------------------------------------

	-- Reads the number displayed on a HUD gauge. The gauge stores the
	-- value as text on the Gradient label, e.g. "12/60".
	GameUI.readGauge = function(path)
		local node = GameUI.find(path)
		if not node then
			return nil
		end
		local text = ""
		if node:IsA("TextLabel") or node:IsA("TextButton") then
			text = node.Text or ""
		else
			local label = node:FindFirstChildWhichIsA("TextLabel", true)
			text = label and label.Text or ""
		end
		local current, maximum = text:match("(%d+)%s*/%s*(%d+)")
		if current then
			return tonumber(current), tonumber(maximum)
		end
		local single = text:match("(%d+)")
		return tonumber(single), nil
	end

	GameUI.blades = function()
		return GameUI.readGauge('HUD.Main.Top["7"].Blades.Inner.Bar.Gradient')
	end

	GameUI.gas = function()
		return GameUI.readGauge('HUD.Main.Top["7"].Gas.Inner.Bar.Gradient')
	end

	-- Mission timer, the game keeps it somewhere in the HUD as mm:ss.
	GameUI.missionTimer = function()
		local hud = GameUI.hud()
		if not hud then
			return nil
		end
		local label = Util.findDeep(hud, function(node)
			if not (node:IsA("TextLabel") or node:IsA("TextButton")) then
				return false
			end
			local text = node.Text or ""
			return text:match("^%d+:%d+$") ~= nil
		end, 10)
		if not label then
			return nil
		end
		local minutes, seconds = label.Text:match("(%d+):(%d+)")
		if not minutes then
			return nil
		end
		return tonumber(minutes) * 60 + tonumber(seconds)
	end

	------------------------------------------------------------------
	-- Rewards screen
	------------------------------------------------------------------

	GameUI.rewardsVisible = function()
		local rewards = GameUI.rewards()
		if not rewards then
			return false
		end
		return rewards.Visible == true
	end

	GameUI.retryButton = function()
		local button = GameUI.find("Rewards.Main.Info.Main.Buttons.Retry")
		if button and Util.isVisible(button) then
			return button
		end
		local matches = GameUI.findClickables(GameUI.rewards(), { "Retry" }, true)
		return matches[1]
	end

	GameUI.leaveButton = function()
		local button = GameUI.find("Rewards.Main.Info.Main.Buttons.Leave_2")
		if button and Util.isVisible(button) then
			return button
		end
		local matches = GameUI.findClickables(GameUI.rewards(), { "Leave" }, true)
		return matches[1]
	end

	------------------------------------------------------------------
	-- Slot selection (lobby)
	------------------------------------------------------------------

	GameUI.selectSlot = function(slot)
		local screen = GameUI.titleScreen()
		if not screen then
			return false
		end
		local direct = screen:FindFirstChild("Slots")
			and screen.Slots:FindFirstChild(slot)
			and screen.Slots[slot]:FindFirstChild("Select_" .. slot)
		if direct then
			Util.click(direct)
			return true
		end
		return GameUI.clickFirst(screen, { "Select_" .. slot, slot }, true)
	end

	------------------------------------------------------------------
	-- Text scraping (used for drop lists)
	------------------------------------------------------------------

	-- Collects the visible text of a container, one entry per label.
	GameUI.collectText = function(root, filter)
		local output = {}
		root = root or GameUI.interface()
		if not root then
			return output
		end
		local labels = Util.findAllDeep(root, function(node)
			return node:IsA("TextLabel") or node:IsA("TextButton")
		end, 12)
		for _, label in ipairs(labels) do
			if Util.isVisible(label) then
				local text = (label.Text or ""):match("^%s*(.-)%s*$")
				if text and text ~= "" then
					if type(filter) == "function" then
						if filter(text, label) then
							table.insert(output, { text = text, node = label })
						end
					else
						table.insert(output, { text = text, node = label })
					end
				end
			end
		end
		return output
	end

	return GameUI
end

end)())

-- ==== Targets ===============================================
__define("Targets", (function()
--[[
	AOTR Suite :: Targets
	Titan discovery, hitbox resolution and classification.

	Fixes implemented here (from the v0276 changelog):
		* Raid bosses that are immune to damage are never registered as a
		  hitbox, so the suite stops wasting attacks on them.
		* The Armored Titan is skipped while it is protecting the boats.
		* Normal titans inside a Colossal Raid are found as well, which is
		  what made spears fail to kill them.
		* Targeting no longer sticks to a dead or removed titan.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Targets = {}

	local Workspace = game:GetService("Workspace")

	local napeCache = setmetatable({}, { __mode = "k" })
	local deadCache = setmetatable({}, { __mode = "k" })

	local SEARCH_FOLDERS = {
		"Titans",
		"Enemies",
		"Boss",
		"Bosses",
		"Raid",
		"RaidTitans",
		"Spawns",
		"Entities",
		"Living",
		"Targets",
	}

	------------------------------------------------------------------
	-- Nape resolution
	------------------------------------------------------------------

	Targets.findNape = function(titan)
		if not titan or not titan.Parent then
			return nil
		end
		local cached = napeCache[titan]
		if cached and cached.Parent and cached:IsDescendantOf(titan) then
			return cached
		end

		local hitboxes = titan:FindFirstChild("Hitboxes")
		local nape = nil
		if hitboxes then
			local hit = hitboxes:FindFirstChild("Hit")
			nape = (hit and hit:FindFirstChild("Nape")) or hitboxes:FindFirstChild("Nape")
		end
		if not nape then
			for _, part in ipairs(titan:GetDescendants()) do
				if part:IsA("BasePart") then
					local name = string.lower(part.Name)
					if name == "nape" or name == "weakpoint" or name == "core" or name == "neck" then
						nape = part
						break
					end
				end
			end
		end
		if nape and nape:IsA("BasePart") then
			napeCache[titan] = nape
			return nape
		end
		return nil
	end

	------------------------------------------------------------------
	-- Classification
	------------------------------------------------------------------

	local IMMUNE_ATTRIBUTES = {
		"Immune",
		"Invulnerable",
		"DamageImmune",
		"CannotBeDamaged",
		"Undodgeable",
	}

	local function attributeIsTrue(model, names)
		for _, name in ipairs(names) do
			if model:GetAttribute(name) == true then
				return true
			end
		end
		return false
	end

	-- A titan is untouchable when the server marked it immune, either
	-- through an attribute or through a boolean child.
	Targets.isImmune = function(model)
		if not model then
			return false
		end
		if attributeIsTrue(model, IMMUNE_ATTRIBUTES) then
			return true
		end
		local flag = Util.findDeep(model, function(node)
			if not node:IsA("BoolValue") then
				return false
			end
			local name = string.lower(node.Name)
			return node.Value == true and (string.find(name, "immun", 1, true) or string.find(name, "invulner", 1, true))
		end, 6)
		return flag ~= nil
	end

	-- The Armored Titan has to be left alone while it shields the boats.
	Targets.isProtectingBoats = function(model)
		if not model then
			return false
		end
		if attributeIsTrue(model, { "ProtectingBoats", "Protecting", "DefendingBoats", "EscortingBoats" }) then
			return true
		end
		for _, name in ipairs({ "ProtectingBoats", "Protecting", "DefendingBoats" }) do
			local value = model:FindFirstChild(name)
			if value and value:IsA("BoolValue") and value.Value == true then
				return true
			end
		end
		return false
	end

	local function cleanName(model)
		if not model then
			return "Titan"
		end
		for _, attribute in ipairs({ "Title", "TitanType", "Type", "Variant", "BossName", "Class" }) do
			local value = model:GetAttribute(attribute)
			if type(value) == "string" and value ~= "" and not value:match("%x+%-%x+") and #value < 24 then
				return value
			end
		end
		local raw = tostring(model.Name)
		if raw:match("%x+%-%x+") or #raw >= 24 then
			if model:FindFirstChild("Abnormal") or model:GetAttribute("Abnormal") == true then
				return "Abnormal Titan"
			elseif model:FindFirstChild("Crawler") or model:GetAttribute("Crawler") == true then
				return "Crawler Titan"
			elseif model:FindFirstChild("Shifter") or model:GetAttribute("Shifter") == true then
				return "Titan Shifter"
			elseif model:FindFirstChild("Boss") or model:GetAttribute("Boss") == true or string.find(string.lower(raw), "colossal", 1, true) then
				return "Boss Titan"
			end
			return "Titan"
		end
		return raw
	end

	------------------------------------------------------------------
	-- Liveness
	------------------------------------------------------------------

	Targets.isAlive = function(entry)
		if not entry or not entry.model or not entry.model.Parent then
			return false
		end
		if deadCache[entry.model] then
			return false
		end
		local humanoid = entry.humanoid
		if humanoid and humanoid.Health <= 0 then
			deadCache[entry.model] = true
			return false
		end
		local nape = entry.nape
		if nape and nape.Parent and type(nape.Transparency) == "number" and nape.Transparency >= 1 and not nape.Anchored then
			-- A removed hitbox means the titan is gone.
			deadCache[entry.model] = true
			return false
		end
		return true
	end

	Targets.markDead = function(model)
		deadCache[model] = true
		napeCache[model] = nil
	end

	------------------------------------------------------------------
	-- Discovery
	------------------------------------------------------------------

	local function collectFolders()
		local folders = {}
		local seen = {}
		local function push(folder)
			if folder and not seen[folder] then
				seen[folder] = true
				table.insert(folders, folder)
			end
		end
		for _, name in ipairs(SEARCH_FOLDERS) do
			push(Workspace:FindFirstChild(name))
		end
		local map = Workspace:FindFirstChild("Map")
		if map then
			for _, child in ipairs(map:GetChildren()) do
				push(child)
			end
		end
		return folders
	end

	-- Titans that live inside a raid are sometimes parented to a nested
	-- model instead of a top level folder, so the raid container is
	-- searched one level deeper.
	local function collectRaidTitans()
		local found = {}
		local seen = {}
		local containers = {
			Workspace:FindFirstChild("Raid"),
			Workspace:FindFirstChild("RaidTitans"),
			Workspace:FindFirstChild("ColossalRaid"),
			Workspace:FindFirstChild("Colossal"),
		}
		for _, container in ipairs(containers) do
			if container then
				for _, child in ipairs(container:GetDescendants()) do
					if child:IsA("Model") and not seen[child] then
						seen[child] = true
						table.insert(found, child)
					end
				end
			end
		end
		return found
	end

	-- The workspace scan is the expensive part, it is cached for a short
	-- time so the heartbeat loop does not walk the world every frame.
	local SCAN_INTERVAL = 0.25
	local scanCache = {}
	local scanTime = 0

	Targets.scan = function(force)
		local now = Util.now()
		if not force and now - scanTime < SCAN_INTERVAL then
			return scanCache
		end
		scanTime = now

		local models = {}
		local seen = {}
		for _, folder in ipairs(collectFolders()) do
			for _, child in ipairs(folder:GetChildren()) do
				if child:IsA("Model") and not seen[child] then
					seen[child] = true
					table.insert(models, child)
				end
			end
		end
		for _, child in ipairs(collectRaidTitans()) do
			if not seen[child] then
				seen[child] = true
				table.insert(models, child)
			end
		end
		scanCache = models
		return scanCache
	end

	Targets.getTitans = function()
		local list = {}
		local player = Util.LocalPlayer
		local character = player and player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")

		for _, model in ipairs(Targets.scan()) do
			if model ~= character then
				local humanoid = model:FindFirstChildOfClass("Humanoid")
				local nape = Targets.findNape(model)
				if nape then
					local name = cleanName(model)
					local lower = string.lower(name .. " " .. model.Name)
					local isBoss = string.find(lower, "boss", 1, true)
						or string.find(lower, "colossal", 1, true)
						or string.find(lower, "armored", 1, true)
						or string.find(lower, "female", 1, true)
						or string.find(lower, "beast", 1, true)
						or string.find(lower, "shifter", 1, true)
						or model:GetAttribute("Boss") == true
					local isCrawler = string.find(lower, "crawler", 1, true) or model:GetAttribute("Crawler") == true
					local isAbnormal = string.find(lower, "abnormal", 1, true) or model:GetAttribute("Abnormal") == true
					local isArmored = string.find(lower, "armored", 1, true) or model:GetAttribute("Armored") == true
					local distance = root and (nape.Position - root.Position).Magnitude or 9999

					table.insert(list, {
						model = model,
						name = name,
						humanoid = humanoid,
						nape = nape,
						dist = distance,
						hp = humanoid and humanoid.Health or 100,
						isBoss = isBoss,
						isCrawler = isCrawler,
						isAbnormal = isAbnormal,
						isArmored = isArmored,
						isImmune = Targets.isImmune(model),
						isProtectingBoats = Targets.isProtectingBoats(model),
					})
				end
			end
		end

		return list
	end

	------------------------------------------------------------------
	-- Sorting
	------------------------------------------------------------------

	Targets.sort = function(list, priority)
		priority = priority or "Closest"
		table.sort(list, function(a, b)
			if priority == "Bosses First" then
				if a.isBoss ~= b.isBoss then
					return a.isBoss
				end
				return a.dist < b.dist
			elseif priority == "Crawlers & Abnormals" then
				local threatA = a.isCrawler or a.isAbnormal or a.isBoss
				local threatB = b.isCrawler or b.isAbnormal or b.isBoss
				if threatA ~= threatB then
					return threatA
				end
				return a.dist < b.dist
			elseif priority == "Lowest HP" then
				if math.abs(a.hp - b.hp) > 50 then
					return a.hp < b.hp
				end
				return a.dist < b.dist
			end
			return a.dist < b.dist
		end)
		return list
	end

	-- Picks the next target, honouring the immunity and the boat rule.
	Targets.pick = function(list, priority)
		priority = priority or "Closest"
		Targets.sort(list, priority)
		for _, entry in ipairs(list) do
			local usable = Targets.isAlive(entry)
			if usable and entry.isImmune then
				-- Immune raid bosses must not be hit at all.
				usable = false
			end
			if usable and entry.isArmored and entry.isProtectingBoats then
				-- The armored titan is busy shielding the boats.
				usable = false
			end
			if usable then
				return entry
			end
		end
		return nil
	end

	-- Collects the extra targets that can be hit with the same swing.
	Targets.neighbours = function(primary, radius, limit)
		local result = {}
		if not primary then
			return result
		end
		local player = Util.LocalPlayer
		local character = player and player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		for _, entry in ipairs(Targets.getTitans()) do
			if entry ~= primary and Targets.isAlive(entry) and not entry.isImmune then
				local toPrimary = (entry.nape.Position - primary.nape.Position).Magnitude
				local toPlayer = root and (entry.nape.Position - root.Position).Magnitude or toPrimary
				if toPrimary <= radius or toPlayer <= radius then
					table.insert(result, entry)
					if #result >= (limit or 4) then
						break
					end
				end
			end
		end
		return result
	end

	return Targets
end

end)())

-- ==== Stats ===============================================
__define("Stats", (function()
--[[
	AOTR Suite :: Stats
	Reads the player currencies and keeps the session counters.

	Pumpkins are a first class currency here: they show up in the player
	stats block and in the drop list of the Discord webhook.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Stats = {}

	local Players = game:GetService("Players")

	-- Currencies the game exposes, with the attribute / leaderstat names
	-- that are used for them.
	Stats.CURRENCIES = {
		{ key = "Gold", label = "Gold", names = { "Gold", "Coins", "Currency" } },
		{ key = "Gems", label = "Gems", names = { "Gems", "Gem", "Diamonds" } },
		{ key = "Canes", label = "Canes", names = { "Canes", "Cane", "Stick" } },
		{ key = "Pumpkins", label = "Pumpkins", names = { "Pumpkins", "Pumpkin" } },
		{ key = "XP", label = "XP", names = { "XP", "Experience", "Exp" } },
		{ key = "Level", label = "Level", names = { "Level", "Rank", "Lv" } },
	}

	------------------------------------------------------------------
	-- Value lookup
	------------------------------------------------------------------

	-- Roblox exposes typeof, the fallback keeps the module usable in a
	-- plain Lua environment.
	local function isInstance(value)
		if typeof then
			return typeof(value) == "Instance"
		end
		return type(value) == "Instance"
	end

	local function readFromStat(value)
		if type(value) == "number" then
			return value
		end
		if type(value) == "string" then
			local number = value:match("(%d+)")
			return tonumber(number)
		end
		if isInstance(value) then
			if value:IsA("NumberValue") or value:IsA("IntValue") or value:IsA("FloatValue") then
				return value.Value
			end
			if value:IsA("StringValue") then
				return tonumber((value.Value or ""):match("(%d+)"))
			end
		end
		return nil
	end

	-- Looks a currency up in leaderstats, in player attributes and in the
	-- replicated data folders the game keeps on the player.
	Stats.readCurrency = function(key)
		local player = Util.LocalPlayer or Players.LocalPlayer
		if not player then
			return nil
		end
		local definition = nil
		for _, entry in ipairs(Stats.CURRENCIES) do
			if entry.key == key then
				definition = entry
				break
			end
		end
		if not definition then
			return nil
		end

		local leaderstats = player:FindFirstChild("leaderstats")
		if leaderstats then
			for _, name in ipairs(definition.names) do
				local value = readFromStat(leaderstats:FindFirstChild(name))
				if value ~= nil then
					return value
				end
			end
		end

		local attributes = player:GetAttributes()
		for _, name in ipairs(definition.names) do
			local value = readFromStat(attributes[name])
			if value ~= nil then
				return value
			end
		end

		-- Some currencies only exist inside a replicated folder.
		for _, folderName in ipairs({ "Stats", "Currencies", "PlayerData", "Data" }) do
			local folder = player:FindFirstChild(folderName)
			if folder then
				for _, name in ipairs(definition.names) do
					local value = readFromStat(folder:FindFirstChild(name))
					if value ~= nil then
						return value
					end
				end
			end
		end

		return nil
	end

	------------------------------------------------------------------
	-- Session counters
	------------------------------------------------------------------

	Stats.session = {
		missions = 0,
		raids = 0,
		waves = 0,
		titansKilled = 0,
		bladesReloaded = 0,
		boostsBought = 0,
		achievementsClaimed = 0,
		questsClaimed = 0,
		startedAt = Util.now(),
	}

	Stats.reset = function()
		Stats.session.missions = 0
		Stats.session.raids = 0
		Stats.session.waves = 0
		Stats.session.titansKilled = 0
		Stats.session.bladesReloaded = 0
		Stats.session.boostsBought = 0
		Stats.session.achievementsClaimed = 0
		Stats.session.questsClaimed = 0
		Stats.session.startedAt = Util.now()
	end

	------------------------------------------------------------------
	-- Snapshot
	------------------------------------------------------------------

	Stats.snapshot = function()
		local snapshot = {}
		for _, entry in ipairs(Stats.CURRENCIES) do
			snapshot[entry.key] = Stats.readCurrency(entry.key)
		end
		snapshot.username = (Util.LocalPlayer and Util.LocalPlayer.Name) or "Unknown"
		snapshot.displayName = (Util.LocalPlayer and Util.LocalPlayer.DisplayName) or "Unknown"
		snapshot.session = Util.deepCopy(Stats.session)
		snapshot.sessionSeconds = Util.now() - Stats.session.startedAt
		return snapshot
	end

	return Stats
end

end)())

-- ==== Safety ===============================================
__define("Safety", (function()
--[[
	AOTR Suite :: Safety
	Mission safety timer.

	Rules implemented:
		* The minimum mission timer is 30 seconds, it can never go below.
		* The timer follows the real in game mission timer when the HUD
		  exposes it, and falls back to a wall clock measurement otherwise.
		* The value reported as "Time Taken" is the real mission duration,
		  not the time the script happened to be running.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Safety = {}

	local MINIMUM_TIMER = 30

	local state = {
		inMission = false,
		startedAt = 0,
		lastDuration = 0,
		lastHudValue = nil,
		rewardsSeen = false,
	}

	------------------------------------------------------------------
	-- Timer amount
	------------------------------------------------------------------

	-- The configured timer, clamped to the hard minimum of 30 seconds.
	Safety.timerAmount = function()
		local configured = 30
		local ok, value = pcall(function()
			return Ctx.Config.Get().SafetyTime
		end)
		if ok and type(value) == "number" then
			configured = value
		end
		return math.max(MINIMUM_TIMER, configured)
	end

	Safety.MINIMUM = MINIMUM_TIMER

	------------------------------------------------------------------
	-- Mission lifecycle
	------------------------------------------------------------------

	local function hudTimer()
		local ok, value = pcall(function()
			return Ctx.GameUI.missionTimer()
		end)
		if ok then
			return value
		end
		return nil
	end

	-- Updates the internal state. Call this every frame.
	Safety.update = function()
		local rewardsVisible = false
		local ok, visible = pcall(function()
			return Ctx.GameUI.rewardsVisible()
		end)
		if ok then
			rewardsVisible = visible == true
		end

		local timer = hudTimer()

		if rewardsVisible then
			if state.inMission then
				state.lastDuration = Safety.elapsed()
				state.inMission = false
				state.startedAt = 0
			end
			state.rewardsSeen = true
			return
		end

		state.rewardsSeen = false

		-- A mission is running when the HUD shows a timer or the player
		-- is inside a map with titans around.
		local running = timer ~= nil
		if not running then
			local okT, titans = pcall(function()
				return Ctx.Targets.getTitans()
			end)
			if okT and titans and #titans > 0 then
				running = true
			end
		end

		if running and not state.inMission then
			state.inMission = true
			state.startedAt = Util.now()
		elseif not running and state.inMission and timer == nil then
			-- The HUD timer vanished without a rewards screen, the player
			-- probably left the map.
			state.inMission = false
			state.startedAt = 0
		end

		state.lastHudValue = timer
	end

	-- Real elapsed mission time in seconds.
	Safety.elapsed = function()
		if state.lastHudValue ~= nil then
			-- The HUD countdown counts down, so the elapsed time is the
			-- mission length minus the remaining time. When the HUD shows
			-- an elapsed counter we detect that by comparing two samples.
			local remaining = state.lastHudValue
			local elapsed = state.trackedElapsed or 0
			if state.lastSampleRemaining ~= nil then
				local delta = state.lastSampleRemaining - remaining
				if delta > 0 and delta < 10 then
					elapsed = (state.trackedElapsed or 0) + delta
					state.trackedElapsed = elapsed
				end
			end
			state.lastSampleRemaining = remaining
			if elapsed > 0 then
				return elapsed
			end
		end
		if state.inMission and state.startedAt > 0 then
			return Util.now() - state.startedAt
		end
		return state.lastDuration
	end

	Safety.inMission = function()
		return state.inMission
	end

	Safety.lastDuration = function()
		return state.lastDuration
	end

	-- True when the safety timer allows leaving the mission.
	Safety.canLeave = function()
		if not state.inMission then
			return true
		end
		return Safety.elapsed() >= Safety.timerAmount()
	end

	-- Seconds left before leaving is allowed.
	Safety.remaining = function()
		if not state.inMission then
			return 0
		end
		return math.max(0, Safety.timerAmount() - Safety.elapsed())
	end

	Safety.reset = function()
		state.inMission = false
		state.startedAt = 0
		state.lastDuration = 0
		state.trackedElapsed = 0
		state.lastSampleRemaining = nil
		state.lastHudValue = nil
		state.rewardsSeen = false
	end

	return Safety
end

end)())

-- ==== Webhook ===============================================
__define("Webhook", (function()
--[[
	AOTR Suite :: Webhook
	Discord reporting.

	Two blocks are sent:
		Player Stats  - includes Pumpkins next to the other currencies
		Drops         - includes Pumpkins next to the other rewards

	"Time Taken" reports the real mission duration that the Safety module
	measured, not the wall clock time of the script.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Webhook = {}

	local previousSnapshot = nil

	------------------------------------------------------------------
	-- Helpers
	------------------------------------------------------------------

	local function config()
		return Ctx.Config.Get()
	end

	Webhook.enabled = function()
		local settings = config()
		return settings.Webhook == true
		and type(settings.WebhookLink) == "string"
		and settings.WebhookLink:match("^https?://") ~= nil
	end

	------------------------------------------------------------------
	-- Drops
	------------------------------------------------------------------

	-- The drop list is built from two sources:
	--   1. the currency delta between the start and the end of a mission
	--   2. the text of the rewards screen
	local function currencyDrops()
		local drops = {}
		if not previousSnapshot then
			return drops
		end
		local current = Ctx.Stats.snapshot()
		for _, entry in ipairs(Ctx.Stats.CURRENCIES) do
			local before = previousSnapshot[entry.key]
			local after = current[entry.key]
			if type(before) == "number" and type(after) == "number" then
				local delta = after - before
				if delta > 0 then
					table.insert(drops, {
						name = entry.label,
						amount = delta,
						text = string.format("+%s %s", Util.formatNumber(delta), entry.label),
					})
				end
			end
		end
		return drops
	end

	local REWARD_SCRAP_PATTERN = "^[%+%-]?[%d%.]+%s+%a"

	-- Scrapes the rewards screen for item names that are not currencies.
	local function screenDrops()
		local drops = {}
		local rewards = Ctx.GameUI.rewards()
		if not rewards or not rewards.Visible then
			return drops
		end
		local entries = Ctx.GameUI.collectText(rewards, function(text)
			return text:match(REWARD_SCRAP_PATTERN) ~= nil
				and not text:match("^[%d%.]+%s+[Ss]econds?$")
		end)
		local seen = {}
		for _, entry in ipairs(entries) do
			local key = string.lower(entry.text)
			if not seen[key] then
				seen[key] = true
				table.insert(drops, {
					name = entry.text,
					amount = nil,
					text = entry.text,
				})
			end
		end
		return drops
	end

	Webhook.collectDrops = function()
		local drops = currencyDrops()
		for _, drop in ipairs(screenDrops()) do
			table.insert(drops, drop)
		end
		return drops
	end

	Webhook.markBaseline = function()
		previousSnapshot = Ctx.Stats.snapshot()
	end

	------------------------------------------------------------------
	-- Embed
	------------------------------------------------------------------

	local function statsFields(snapshot, duration)
		local settings = config()
		local fields = {}

		if settings.ShowUsername ~= false then
			table.insert(fields, {
				name = "Player",
				value = string.format("%s (%s)", snapshot.displayName, snapshot.username),
				inline = true,
			})
		end

		table.insert(fields, {
			name = "Time Taken",
			value = Util.formatDuration(duration),
			inline = true,
		})

		local currencies = {}
		for _, entry in ipairs(Ctx.Stats.CURRENCIES) do
			local value = snapshot[entry.key]
			if type(value) == "number" then
				table.insert(currencies, string.format("%s: %s", entry.label, Util.formatNumber(value)))
			end
		end
		if #currencies > 0 then
			table.insert(fields, {
				name = "Player Stats",
				value = table.concat(currencies, "\n"),
				inline = false,
			})
		end

		local session = snapshot.session
		table.insert(fields, {
			name = "Session",
			value = table.concat({
				string.format("Missions: %d", session.missions),
				string.format("Raids: %d", session.raids),
				string.format("Waves: %d", session.waves),
				string.format("Titans: %d", session.titansKilled),
				string.format("Reloads: %d", session.bladesReloaded),
			}, "\n"),
			inline = false,
		})

		return fields
	end

	local function dropFields(drops)
		local lines = {}
		for _, drop in ipairs(drops) do
			table.insert(lines, drop.text)
		end
		if #lines == 0 then
			return {}
		end
		return {
			{
				name = "Drops",
				value = table.concat(lines, "\n"),
				inline = false,
			},
		}
	end

	Webhook.buildPayload = function(title, duration, drops)
		local snapshot = Ctx.Stats.snapshot()
		local fields = statsFields(snapshot, duration)
		local extra = dropFields(drops or {})
		for _, field in ipairs(extra) do
			table.insert(fields, field)
		end
		return {
			embeds = {
				{
					title = title or "Attack on Titan: Revolution",
					color = 11141375,
					timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
					fields = fields,
					footer = { text = "AOTR Suite" },
				},
			},
		}
	end

	------------------------------------------------------------------
	-- Sending
	------------------------------------------------------------------

	Webhook.send = function(title, duration, drops)
		if not Webhook.enabled() then
			return false
		end
		local payload = Webhook.buildPayload(title, duration, drops)
		local body = Util.jsonEncode(payload)
		if not body then
			return false
		end
		local response = Util.httpRequest({
			Url = config().WebhookLink,
			Method = "POST",
			Headers = { ["Content-Type"] = "application/json" },
			Body = body,
		})
		if not response then
			Util.warn("webhook request failed")
			return false
		end
		return true
	end

	-- Sends the end of mission report with the real mission duration.
	Webhook.reportMission = function(drops)
		local duration = Ctx.Safety.lastDuration()
		if duration <= 0 then
			duration = Ctx.Safety.elapsed()
		end
		return Webhook.send("Mission Report", duration, drops)
	end

	Webhook.test = function()
		return Webhook.send("Webhook Test", 0, {})
	end

	return Webhook
end

end)())

-- ==== Farm ===============================================
__define("Farm", (function()
--[[
	AOTR Suite :: Features / Farm
	Auto farm with the redesigned Blade and Hover methods plus the
	Teleport method.

	Methods
		Blade    - sits right behind the nape, the safe way to farm
		Hover    - flies above the titan at HoverHeight
		Teleport - warps straight onto the nape

	The chosen target is published on Ctx.state.target so the combat and
	reload modules can work on the same titan.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Farm = {}

	local state = {
		target = nil,
		lastTargetId = nil,
		smoothed = nil,
		killCooldown = 0,
	}

	------------------------------------------------------------------
	-- Movement helpers
	------------------------------------------------------------------

	local function characterParts()
		local player = Util.LocalPlayer
		local character = player and player.Character
		if not character then
			return nil, nil, nil
		end
		local root = character:FindFirstChild("HumanoidRootPart")
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		return character, root, humanoid
	end

	-- Position the player wants to be in for the current method.
	local function desiredPosition(method, entry, settings)
		local nape = entry.nape
		if method == "Teleport" then
			return nape.CFrame * CFrame.new(0, 2, -(settings.BehindNapeDistance or 2))
		end
		if method == "Hover" then
			local height = settings.HoverHeight or 265
			return CFrame.new(nape.Position.X, nape.Position.Y + height, nape.Position.Z)
		end
		-- Blade, behind the nape on the neck axis.
		local distance = settings.BehindNapeDistance or 2
		return nape.CFrame * CFrame.new(0, 0, -distance)
	end

	------------------------------------------------------------------
	-- Target management
	------------------------------------------------------------------

	Farm.currentTarget = function()
		return state.target
	end

	Farm.clearTarget = function()
		if state.target and state.target.model then
			Ctx.Targets.markDead(state.target.model)
		end
		state.target = nil
		state.lastTargetId = nil
	end

	local function acquireTarget(settings)
		local list = Ctx.Targets.getTitans()
		local entry = Ctx.Targets.pick(list, settings.TargetPriority)
		if entry and state.lastTargetId == entry.model and not Ctx.Targets.isAlive(entry) then
			entry = nil
		end
		if entry then
			state.target = entry
			state.lastTargetId = entry.model
		end
		return entry
	end

	------------------------------------------------------------------
	-- Main update
	------------------------------------------------------------------

	Farm.update = function(deltaTime)
		local settings = Ctx.Config.Get()
		if settings.AutoFarm ~= true then
			if state.target then
				Farm.clearTarget()
			end
			return
		end

		local character, root, humanoid = characterParts()
		if not root or not humanoid or humanoid.Health <= 0 then
			return
		end

		local entry = state.target
		if not entry or not Ctx.Targets.isAlive(entry) then
			entry = acquireTarget(settings)
		end
		if not entry then
			return
		end

		local method = settings.FarmMethod or "Blade"
		local target = desiredPosition(method, entry, settings)

		if method == "Teleport" or settings.TeleportTitans == true then
			-- Instant warp, no interpolation.
			root.CFrame = target
		else
			-- Smooth flight towards the target position.
			local speed = settings.HoverSpeed or 3000
			local alpha = Util.clamp((speed / 60) * (deltaTime or 0.016) / math.max(1, (root.Position - target.Position).Magnitude), 0, 1)
			if alpha <= 0 then
				alpha = 1
			end
			root.CFrame = root.CFrame:Lerp(target, alpha)
		end

		if settings.DisableHovering ~= true then
			-- Keep the player in the air, this stops the game from
			-- dropping the character onto the titan.
			root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
		end

		Ctx.state.target = entry
	end

	------------------------------------------------------------------
	-- Nape extender
	------------------------------------------------------------------

	-- Grows the nape hitbox so the swings connect more reliably.
	Farm.extendNapes = function()
		local settings = Ctx.Config.Get()
		if settings.NapeExtend ~= true then
			return
		end
		for _, entry in ipairs(Ctx.Targets.getTitans()) do
			local nape = entry.nape
			if nape and nape.Parent then
				local weld = nape:FindFirstChild("Nape")
				if weld and weld:IsA("Weld") then
					weld.Destroy()
				end
				nape.CanCollide = false
				nape.Transparency = math.min(nape.Transparency, 0.85)
				local size = nape.Size
				if size.X < 12 or size.Y < 12 then
					nape.Size = Vector3.new(math.max(size.X, 12), math.max(size.Y, 12), math.max(size.Z, 12))
				end
			end
		end
	end

	Farm.state = state

	return Farm
end

end)())

-- ==== Combat ===============================================
__define("Combat", (function()
--[[
	AOTR Suite :: Features / Combat
	Swings, spears, multi hit and the damage extender.

	Server API used:
		POST("Attacks", "Slash", true)
		POST("Attacks", "Slash_Release")
		POST("Attacks", "M1")
		POST("Hitboxes", "Register", <BasePart>, <damage>, <crit>)
		POST("S_Equipment", "Spears", "Fire", <Vector3>)
		POST("Attacks", "Spears", <Vector3>)
]]

return function(Ctx)
	local Util = Ctx.Util
	local Combat = {}

	local state = {
		lastSlash = 0,
		lastSpear = 0,
		slashCount = 0,
	}

	local BASE_DAMAGE = 500
	local BASE_CRIT = 100

	------------------------------------------------------------------
	-- Damage
	------------------------------------------------------------------

	-- The damage extender scales the damage value that is registered on
	-- the hitbox. 1 means untouched, higher values hit harder.
	Combat.damageScale = function(settings)
		if settings.DamageExtender ~= true then
			return 1
		end
		return Util.clamp(settings.DamageMultiplier or 1, 1, 50)
	end

	local function damageArguments(settings)
		local scale = Combat.damageScale(settings)
		if scale > 1 then
			return math.floor(BASE_DAMAGE * scale), math.floor(BASE_CRIT * scale)
		end
		return BASE_DAMAGE, BASE_CRIT
	end

	------------------------------------------------------------------
	-- Target gathering
	------------------------------------------------------------------

	-- Builds the list of hitboxes a single swing should touch.
	Combat.targetsFor = function(primary, settings)
		local list = {}
		if not primary or not primary.nape then
			return list
		end
		table.insert(list, primary)

		local limit = Util.clamp(settings.MultiHit or 1, 1, 10)
		if limit > 1 then
			local radius = settings.HitDistance or 1000
			for _, entry in ipairs(Ctx.Targets.neighbours(primary, radius, limit - 1)) do
				table.insert(list, entry)
			end
		end
		return list
	end

	------------------------------------------------------------------
	-- Slash
	------------------------------------------------------------------

	Combat.slash = function(primary, settings)
		local now = Util.now()
		if now - state.lastSlash < 0.12 then
			return false
		end
		state.lastSlash = now
		state.slashCount = state.slashCount + 1

		local damage, crit = damageArguments(settings)

		for _, entry in ipairs(Combat.targetsFor(primary, settings)) do
			if entry.nape and entry.nape.Parent then
				-- Immune titans are skipped, the server would ignore the
				-- damage anyway and the swing would be wasted.
				if not entry.isImmune then
					Ctx.Remotes.registerHitbox(entry.nape, damage, crit)
					-- A boss gets the extra hits that the config asks for.
					if entry.isBoss then
						local extra = Util.clamp(settings.BossDamage or 0, 0, 20)
						for _ = 1, extra do
							Ctx.Remotes.registerHitbox(entry.nape, damage, crit)
						end
					end
				end
			end
		end

		Ctx.Remotes.slash()
		Util.pressMouse()
		return true
	end

	------------------------------------------------------------------
	-- Spears
	------------------------------------------------------------------

	-- Fires the thunder spears. When infinite spears is on the ammo is
	-- topped up before every burst so the spear never runs dry.
	Combat.spears = function(primary, settings)
		local now = Util.now()
		if now - state.lastSpear < 0.4 then
			return false
		end
		state.lastSpear = now

		local damage, crit = damageArguments(settings)

		for _, entry in ipairs(Combat.targetsFor(primary, settings)) do
			if entry.nape and entry.nape.Parent and not entry.isImmune then
				Ctx.Remotes.fireSpears(entry.nape.Position)
				Ctx.Remotes.registerHitbox(entry.nape, damage, crit)
			end
		end

		if settings.InfiniteSpears == true then
			-- Keep the spear ammo topped up.
			Ctx.Remotes.refill()
		end
		return true
	end

	------------------------------------------------------------------
	-- Boss mechanics
	------------------------------------------------------------------

	-- The Armored Titan has plated limbs that have to be unlocked before
	-- the nape can be hit.
	Combat.registerBossLimbs = function(entry)
		if not entry or not entry.model then
			return
		end
		local limbs = { "Leg_L", "Leg_R", "Knee_L", "Knee_R", "Ankle_L", "Ankle_R", "Arm_L", "Arm_R" }
		for _, name in ipairs(limbs) do
			local part = entry.model:FindFirstChild(name, true)
			if part and part:IsA("BasePart") then
				Ctx.Remotes.registerHitbox(part, BASE_DAMAGE, BASE_CRIT)
			end
		end
	end

	------------------------------------------------------------------
	-- Main update
	------------------------------------------------------------------

	Combat.update = function()
		local settings = Ctx.Config.Get()
		if settings.AutoFarm ~= true then
			return
		end

		local primary = Ctx.state.target
		if not primary then
			return
		end
		if not Ctx.Targets.isAlive(primary) then
			Ctx.state.target = nil
			return
		end

		-- Spear burst first, it removes the cheap titans quickly.
		Combat.spears(primary, settings)

		if settings.AutoUseSkills == true then
			Combat.useSkills()
		end

		if primary.isBoss then
			Combat.registerBossLimbs(primary)
		end

		Combat.slash(primary, settings)
	end

	------------------------------------------------------------------
	-- Skills
	------------------------------------------------------------------

	-- Casts the equipped hotbar skill when it is off cooldown.
	Combat.useSkills = function()
		local player = Util.LocalPlayer
		local character = player and player.Character
		if not character then
			return false
		end
		local backpack = player:FindFirstChildOfClass("Backpack")
		if not backpack then
			return false
		end
		local cast = false
		for _, tool in ipairs(backpack:GetChildren()) do
			if tool:IsA("Tool") then
				local slot = tool:FindFirstChild("abilitySlot")
				local cooldown = tool:FindFirstChild("Cooldown") or tool:FindFirstChild("cooldown")
				local ready = true
				if cooldown and cooldown:IsA("NumberValue") then
					ready = cooldown.Value <= 0
				end
				if slot and ready then
					local event = tool:FindFirstChild("localEvent")
					if event and event:IsA("BindableEvent") then
						pcall(function()
							event:Fire()
						end)
						cast = true
					end
				end
			end
		end
		return cast
	end

	Combat.state = state

	return Combat
end

end)())

-- ==== Reload ===============================================
__define("Reload", (function()
--[[
	AOTR Suite :: Features / Reload
	Redesigned auto reload.

	When the blades break the player walks to a refill station and refills
	there instead of refilling on the spot. The station that is selected is
	the safest one, meaning the one that has the most distance to the
	nearest titan, unless the config asks for the nearest station.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Reload = {}

	local Workspace = game:GetService("Workspace")

	local state = {
		lastReload = 0,
		atStation = false,
		station = nil,
		slashCounter = 0,
	}

	local STATION_KEYWORDS = {
		"refill",
		"supply",
		"supplies",
		"station",
		"gastank",
		"gas tank",
		"horse",
		"resupply",
		"depot",
	}

	------------------------------------------------------------------
	-- Blade state
	------------------------------------------------------------------

	-- Detects a broken blade using the character attributes first, then
	-- the HUD gauge and finally the amount of swings that happened.
	Reload.isBroken = function()
		local player = Util.LocalPlayer
		local character = player and player.Character
		if not character then
			return false
		end

		if character:GetAttribute("BladesBroken") == true
			or character:GetAttribute("Broken") == true
			or character:GetAttribute("BladeBroken") == true then
			return true
		end

		local durability = character:GetAttribute("Durability") or character:GetAttribute("BladeDurability")
		if type(durability) == "number" then
			return durability <= 2
		end

		local tool = character:FindFirstChildOfClass("Tool")
		if tool then
			local toolDurability = tool:GetAttribute("Durability") or tool:GetAttribute("Dur")
			if type(toolDurability) == "number" then
				return toolDurability <= 2
			end
		end

		local blades, maximum = Ctx.GameUI.blades()
		if blades and maximum and maximum > 0 then
			return blades <= 1
		end

		return false
	end

	------------------------------------------------------------------
	-- Stations
	------------------------------------------------------------------

	local function promptPosition(prompt)
		local parent = prompt.Parent
		if not parent then
			return nil
		end
		if parent:IsA("BasePart") then
			return parent.Position
		end
		if parent:IsA("Model") then
			return parent:GetPivot().Position
		end
		return nil
	end

	-- Collects every refill station that is currently loaded.
	Reload.stations = function()
		local stations = {}
		local player = Util.LocalPlayer
		local character = player and player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")

		for _, prompt in ipairs(Workspace:GetDescendants()) do
			if prompt:IsA("ProximityPrompt") then
				local haystack = string.lower(prompt.Name .. " " .. prompt.ActionText .. " " .. prompt.ObjectText)
				local matches = false
				for _, keyword in ipairs(STATION_KEYWORDS) do
					if string.find(haystack, keyword, 1, true) then
						matches = true
						break
					end
				end
				if matches then
					local position = promptPosition(prompt)
					if position then
						table.insert(stations, {
							prompt = prompt,
							position = position,
							distance = root and (position - root.Position).Magnitude or 9999,
						})
					end
				end
			end
		end

		-- Some maps use a plain part instead of a prompt.
		for _, part in ipairs(Workspace:GetDescendants()) do
			if part:IsA("BasePart") then
				local haystack = string.lower(part.Name)
				for _, keyword in ipairs({ "refill", "gastank", "supplystation" }) do
					if string.find(haystack, keyword, 1, true) then
						local position = part.Position
						table.insert(stations, {
							prompt = nil,
							position = position,
							distance = root and (position - root.Position).Magnitude or 9999,
						})
						break
					end
				end
			end
		end

		return stations
	end

	-- Scores a station by how safe it is. A station that is far away from
	-- every titan is the safe one.
	local function safetyScore(station)
		local nearestTitan = math.huge
		for _, entry in ipairs(Ctx.Targets.getTitans()) do
			if entry.nape and entry.nape.Parent then
				local distance = (entry.nape.Position - station.position).Magnitude
				if distance < nearestTitan then
					nearestTitan = distance
				end
			end
		end
		if nearestTitan == math.huge then
			nearestTitan = 500
		end
		return nearestTitan
	end

	-- Picks the station that should be used.
	Reload.pickStation = function(settings)
		local stations = Reload.stations()
		if #stations == 0 then
			return nil
		end
		local mode = settings.ReloadStation or "Safest"
		local best = stations[1]
		local bestScore
		if mode == "Nearest" then
			bestScore = best.distance
			for _, station in ipairs(stations) do
				if station.distance < bestScore then
					best = station
					bestScore = station.distance
				end
			end
		else
			bestScore = safetyScore(best)
			for _, station in ipairs(stations) do
				local score = safetyScore(station)
				if score > bestScore then
					best = station
					bestScore = score
				end
			end
		end
		return best
	end

	------------------------------------------------------------------
	-- Refill
	------------------------------------------------------------------

	local function triggerPrompt(prompt)
		if not prompt then
			return false
		end
		if type(fireproximityprompt) == "function" then
			local ok = pcall(fireproximityprompt, prompt)
			if ok then
				return true
			end
		end
		return false
	end

	local function moveTo(station)
		local player = Util.LocalPlayer
		local character = player and player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not root or not station then
			return false
		end
		local destination = station.position + Vector3.new(0, 3, 0)
		root.CFrame = CFrame.new(destination)
		return true
	end

	-- Performs the reload: walk to the station, trigger it, refill.
	Reload.perform = function(force)
		local settings = Ctx.Config.Get()
		local now = Util.now()
		if now - state.lastReload < 1 then
			return false
		end
		state.lastReload = now

		local station = Reload.pickStation(settings)
		if station then
			state.station = station
			moveTo(station)
			task.wait(0.15)
			triggerPrompt(station.prompt)
		end

		-- The server side refill works from anywhere and is the reliable
		-- part of the reload.
		Ctx.Remotes.refill()
		state.slashCounter = 0
		Ctx.Stats.session.bladesReloaded = Ctx.Stats.session.bladesReloaded + 1
		return true
	end

	------------------------------------------------------------------
	-- Auto refill of the supplies
	------------------------------------------------------------------

	-- Tops the gas and the blades up without leaving the fight.
	Reload.refillSupplies = function()
		local settings = Ctx.Config.Get()
		if settings.AutoRefill ~= true then
			return false
		end
		local now = Util.now()
		if now - (state.lastRefill or 0) < 2 then
			return false
		end
		state.lastRefill = now
		Ctx.Remotes.refill()
		return true
	end

	------------------------------------------------------------------
	-- Main update
	------------------------------------------------------------------

	Reload.update = function()
		local settings = Ctx.Config.Get()

		if settings.AutoRefill == true then
			Reload.refillSupplies()
		end

		if settings.AutoReload ~= true then
			return
		end

		-- Count the swings so the reload also triggers when the game does
		-- not report the durability.
		state.slashCounter = state.slashCounter + 1
		if not Reload.isBroken() and state.slashCounter < 40 then
			return
		end

		Reload.perform()
	end

	Reload.state = state

	return Reload
end

end)())

-- ==== Claim ===============================================
__define("Claim", (function()
--[[
	AOTR Suite :: Features / Claim
	Auto claim for achievements, quests, battle pass quests and the daily
	reward.

	The daily reward has no toggle on purpose, it is always active.
	Everything is driven through the game interface by keyword, which keeps
	working when the game moves its panels around. A remote fallback exists
	for the parts that are not exposed as a button.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Claim = {}

	local state = {
		lastRun = 0,
		achievements = 0,
		quests = 0,
		battlePass = 0,
		daily = 0,
	}

	------------------------------------------------------------------
	-- Helpers
	------------------------------------------------------------------

	local function config()
		return Ctx.Config.Get()
	end

	-- Opens a panel of the interface by keyword and returns its root.
	local function openPanel(keywords)
		local matches = Ctx.GameUI.findClickables(Ctx.GameUI.interface(), keywords, true)
		if #matches == 0 then
			return nil
		end
		Util.click(matches[1])
		task.wait(0.35)
		-- The opened panel is the deepest visible frame that contains the
		-- word we searched for.
		local root = nil
		for _, node in ipairs(Ctx.GameUI.findClickables(Ctx.GameUI.interface(), keywords, true)) do
			local ancestor = node
			while ancestor and ancestor:IsA("GuiObject") do
				if ancestor.Name:lower():find("panel", 1, true) or ancestor.Name:lower():find("menu", 1, true) then
					root = ancestor
					break
				end
				ancestor = ancestor.Parent
			end
			if root then
				break
			end
		end
		return root or Ctx.GameUI.interface()
	end

	-- Clicks every enabled claim button inside a root.
	local function claimButtons(root, keywords)
		local count = 0
		local buttons = Ctx.GameUI.findClickables(root, keywords, true)
		for _, button in ipairs(buttons) do
			if button:IsA("GuiObject") and button.Active and button.Selectable ~= false then
				if Util.click(button) then
					count = count + 1
					task.wait(0.12)
				end
			end
		end
		return count
	end

	------------------------------------------------------------------
	-- Achievements
	------------------------------------------------------------------

	Claim.achievements = function()
		local root = openPanel({ "Achievements", "Achievement" })
		if not root then
			return 0
		end
		local count = claimButtons(root, { "Claim" })
		-- Some layouts need the dedicated "Claim All" button.
		if count == 0 then
			count = claimButtons(root, { "Claim All" })
		end
		state.achievements = state.achievements + count
		if count > 0 then
			Ctx.Stats.session.achievementsClaimed = Ctx.Stats.session.achievementsClaimed + count
		end
		return count
	end

	------------------------------------------------------------------
	-- Quests (including the battle pass)
	------------------------------------------------------------------

	Claim.quests = function()
		local root = openPanel({ "Quests", "Quest" })
		if not root then
			return 0
		end
		local count = claimButtons(root, { "Claim" })
		count = count + claimButtons(root, { "Claim All" })
		state.quests = state.quests + count
		if count > 0 then
			Ctx.Stats.session.questsClaimed = Ctx.Stats.session.questsClaimed + count
		end
		return count
	end

	-- The battle pass quests live in their own tab of the quest panel.
	Claim.battlePass = function()
		local root = openPanel({ "Quests", "Quest" })
		if not root then
			return 0
		end
		local tabs = Ctx.GameUI.findClickables(root, { "Battle Pass", "BattlePass", "Season" }, true)
		for _, tab in ipairs(tabs) do
			Util.click(tab)
			task.wait(0.3)
			break
		end
		local count = claimButtons(root, { "Claim" })
		count = count + claimButtons(root, { "Claim All" })
		state.battlePass = state.battlePass + count
		return count
	end

	------------------------------------------------------------------
	-- Daily reward, always active
	------------------------------------------------------------------

	Claim.dailyReward = function()
		local root = openPanel({ "Daily Reward", "DailyRewards", "Daily", "Login Reward" })
		if not root then
			return 0
		end
		local count = claimButtons(root, { "Claim" })
		count = count + claimButtons(root, { "Collect", "Redeem" })
		state.daily = state.daily + count
		return count
	end

	------------------------------------------------------------------
	-- Remote fallback
	------------------------------------------------------------------

	-- Some claim actions are only reachable through the server. The
	-- signature that works is remembered for the rest of the session.
	local function remoteFallback()
		Ctx.Remotes.postAny("claim_achievement", {
			{ "Achievements", "Claim" },
			{ "Achievement", "Claim" },
			{ "Quests", "Claim" },
		})
	end

	------------------------------------------------------------------
	-- Main update
	------------------------------------------------------------------

	Claim.update = function()
		local settings = config()
		local now = Util.now()
		if now - state.lastRun < 3 then
			return
		end
		state.lastRun = now

		-- The daily reward is always claimed, there is no toggle for it.
		Claim.dailyReward()

		if settings.ClaimAchievements == true then
			if Claim.achievements() == 0 then
				remoteFallback()
			end
		end

		if settings.ClaimQuests == true then
			Claim.quests()
			if settings.ClaimBattlePass ~= false then
				Claim.battlePass()
			end
		end
	end

	Claim.state = state

	return Claim
end

end)())

-- ==== Boosts ===============================================
__define("Boosts", (function()
--[[
	AOTR Suite :: Features / Boosts
	Boost purchase with a selectable currency.

	Supported currencies: Canes, Gems and Pumpkins.
	The currency is picked in the shop panel, the boosts are then bought one
	by one. A remote fallback is used for the parts of the shop that do not
	expose a button.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Boosts = {}

	local state = {
		lastRun = 0,
		bought = 0,
		currency = nil,
	}

	local function config()
		return Ctx.Config.Get()
	end

	------------------------------------------------------------------
	-- Shop panel
	------------------------------------------------------------------

	local function openShop()
		local matches = Ctx.GameUI.findClickables(Ctx.GameUI.interface(), { "Shop", "Store", "Boosts" }, true)
		if #matches == 0 then
			return nil
		end
		Util.click(matches[1])
		task.wait(0.35)
		return Ctx.GameUI.interface()
	end

	------------------------------------------------------------------
	-- Currency
	------------------------------------------------------------------

	-- Selects the currency the boosts are paid with.
	Boosts.selectCurrency = function(root, currency)
		local options = Ctx.GameUI.findClickables(root, { currency }, true)
		for _, option in ipairs(options) do
			-- A currency entry is a button that either holds the currency
			-- name or sits next to it.
			Util.click(option)
			state.currency = currency
			task.wait(0.2)
			return true
		end
		return false
	end

	------------------------------------------------------------------
	-- Buying
	------------------------------------------------------------------

	-- Buys a single boost by name.
	Boosts.buy = function(root, boostName)
		local entries = Ctx.GameUI.findClickables(root, { boostName }, true)
		for _, entry in ipairs(entries) do
			-- The buy button usually sits inside the entry.
			local buy = entry:FindFirstChild("Buy", true)
			if not buy then
				buy = Ctx.GameUI.findClickables(entry, { "Buy", "Purchase" }, true)[1]
			end
			if buy and Util.isVisible(buy) then
				if Util.click(buy) then
					state.bought = state.bought + 1
					Ctx.Stats.session.boostsBought = Ctx.Stats.session.boostsBought + 1
					task.wait(0.25)
					return true
				end
			end
			-- Some layouts make the whole entry the button.
			if entry:IsA("TextButton") or entry:IsA("ImageButton") then
				if Util.click(entry) then
					state.bought = state.bought + 1
					Ctx.Stats.session.boostsBought = Ctx.Stats.session.boostsBought + 1
					task.wait(0.25)
					return true
				end
			end
		end
		return false
	end

	------------------------------------------------------------------
	-- Remote fallback
	------------------------------------------------------------------

	Boosts.remoteBuy = function(boostName, currency)
		Ctx.Remotes.postAny("buy_boost", {
			{ "Boosts", "Purchase", boostName, currency },
			{ "S_Equipment", "Boost", boostName, currency },
			{ "Shop", "Buy", boostName, currency },
		})
	end

	------------------------------------------------------------------
	-- Main update
	------------------------------------------------------------------

	Boosts.update = function()
		local settings = config()
		if settings.BuyBoosts ~= true then
			return
		end
		local now = Util.now()
		if now - state.lastRun < 5 then
			return
		end
		state.lastRun = now

		local currency = settings.ItemtoBuyWith or "Canes"
		local root = openShop()
		if not root then
			return
		end

		Boosts.selectCurrency(root, currency)

		local list = settings.Boosts
		if type(list) == "string" then
			list = { list }
		end
		if type(list) ~= "table" then
			return
		end
		for _, boost in ipairs(list) do
			if type(boost) == "string" and boost ~= "" then
				if not Boosts.buy(root, boost) then
					Boosts.remoteBuy(boost, currency)
				end
			end
		end
	end

	Boosts.state = state

	return Boosts
end

end)())

-- ==== AutoStart ===============================================
__define("AutoStart", (function()
--[[
	AOTR Suite :: Features / AutoStart
	Creates missions and raids on its own.

	Difficulties supported (from the in game ladder):
		Easy, Normal, Hard, Severe, Aberrant, Freedom
	plus the top tier "Hardest (w/ Freedom)" which needs Freedom unlocked.
]]

return function(Ctx)
	local Util = Ctx.Util
	local AutoStart = {}

	local state = {
		lastRun = 0,
		running = false,
		started = 0,
	}

	local MAP_SUFFIX = "_Missions"

	local function config()
		return Ctx.Config.Get()
	end

	------------------------------------------------------------------
	-- Difficulty
	------------------------------------------------------------------

	-- Returns the difficulty entry of the config.
	AutoStart.difficulty = function()
		local settings = config()
		local wanted = settings.AutoStartDifficulty or "Hardest (w/ Freedom)"
		for _, entry in ipairs(Ctx.Config.DIFFICULTIES) do
			if entry.name == wanted then
				return entry
			end
		end
		return Ctx.Config.DIFFICULTIES[#Ctx.Config.DIFFICULTIES]
	end

	-- Clicks the difficulty button inside the mission panel.
	local function selectDifficulty(root, name)
		local matches = Ctx.GameUI.findClickables(root, { name }, true)
		if #matches == 0 then
			return false
		end
		Util.click(matches[1])
		task.wait(0.2)
		return true
	end

	------------------------------------------------------------------
	-- Missions
	------------------------------------------------------------------

	local function openMissionMap()
		-- Interface.Missions.Prompt.Selection.Missions
		local prompt = Ctx.GameUI.find("Missions.Prompt.Selection.Missions")
		if prompt and Util.isVisible(prompt) then
			Util.click(prompt)
			task.wait(0.3)
			return true
		end
		return Ctx.GameUI.openMenu("Missions")
	end

	local function selectMap(mapName)
		-- Interface.Missions.Missions.Main.Maps.Maps.<Map>_Missions
		local maps = Ctx.GameUI.find("Missions.Missions.Main.Maps.Maps")
		if maps then
			local entry = maps:FindFirstChild(mapName .. MAP_SUFFIX) or maps:FindFirstChild(mapName)
			if entry then
				Util.click(entry)
				task.wait(0.25)
				return true
			end
		end
		return Ctx.GameUI.clickFirst(Ctx.GameUI.missions(), { mapName }, true)
	end

	local function createMission()
		-- Interface.Missions.Missions.Main.Info.Main.Buttons.Creation_Missions
		local button = Ctx.GameUI.find("Missions.Missions.Main.Info.Main.Buttons.Creation_Missions")
		if button and Util.isVisible(button) then
			Util.click(button)
			task.wait(0.3)
			return true
		end
		return Ctx.GameUI.clickFirst(Ctx.GameUI.missions(), { "Creation", "Create" }, true)
	end

	local function applyModifiers(modifiers)
		if type(modifiers) ~= "table" or #modifiers == 0 then
			return
		end
		-- Interface.Missions.Info.Main.Info.Modifiers.Modifiers_Buttons
		local opener = Ctx.GameUI.find("Missions.Info.Main.Info.Modifiers.Modifiers_Buttons")
		if opener and Util.isVisible(opener) then
			Util.click(opener)
			task.wait(0.3)
		else
			Ctx.GameUI.clickFirst(Ctx.GameUI.missions(), { "Modifiers" }, true)
			task.wait(0.3)
		end

		local options = Ctx.GameUI.find("Missions.Info.Main.Info.Modifiers.Options")
		if options then
			for _, modifier in ipairs(modifiers) do
				local option = options:FindFirstChild(modifier)
				if option and option:IsA("GuiObject") then
					Util.click(option)
					task.wait(0.12)
				end
			end
		end

		-- Interface.Missions.Info.Main.Info.Modifiers.Modifiers_Buttons.Modifiers_Return
		local closer = Ctx.GameUI.find("Missions.Info.Main.Info.Modifiers.Modifiers_Buttons.Modifiers_Return")
		if closer and Util.isVisible(closer) then
			Util.click(closer)
			task.wait(0.25)
		else
			Ctx.GameUI.clickFirst(Ctx.GameUI.missions(), { "Return", "Close" }, true)
		end
	end

	local function beginMission()
		-- Interface.Missions.Info.Main.Info.Main.Info_Buttons.Begin
		local begin = Ctx.GameUI.find("Missions.Info.Main.Info.Main.Info_Buttons.Begin")
		if begin and Util.isVisible(begin) then
			Util.click(begin)
			return true
		end
		return Ctx.GameUI.clickFirst(Ctx.GameUI.missions(), { "Begin", "Start" }, true)
	end

	AutoStart.startMission = function()
		local settings = config()
		if not openMissionMap() then
			return false
		end
		if settings.PlayBoostedMap == true then
			-- Prefer a map that carries a boost.
			local maps = Ctx.GameUI.find("Missions.Missions.Main.Maps.Maps")
			if maps then
				for _, child in ipairs(maps:GetChildren()) do
					if child:FindFirstChild("Boost") then
						Util.click(child)
						task.wait(0.25)
						break
					end
				end
			end
		else
			selectMap(settings.AutoStartMap or "Shiganshina")
		end

		if not createMission() then
			return false
		end

		local panel = Ctx.GameUI.missions() or Ctx.GameUI.interface()
		local difficulty = AutoStart.difficulty()
		selectDifficulty(panel, difficulty.name)
		applyModifiers(settings.AutoStartModifiers)

		if not beginMission() then
			return false
		end
		state.started = Util.now()
		return true
	end

	------------------------------------------------------------------
	-- Raids
	------------------------------------------------------------------

	AutoStart.startRaid = function()
		local settings = config()
		if not Ctx.GameUI.openMenu("Raids") then
			if not Ctx.GameUI.openMenu("Raid") then
				return false
			end
		end
		task.wait(0.3)
		local panel = Ctx.GameUI.interface()
		local difficulty = AutoStart.difficulty()
		selectDifficulty(panel, difficulty.name)
		if not Ctx.GameUI.clickFirst(panel, { "Begin", "Start", "Launch" }, true) then
			return false
		end
		state.started = Util.now()
		return true
	end

	------------------------------------------------------------------
	-- Main update
	------------------------------------------------------------------

	AutoStart.update = function()
		local settings = config()
		if settings.AutoStart ~= true then
			state.running = false
			return
		end

		-- Never start a new mission while one is running.
		if Ctx.Safety.inMission() then
			return
		end

		local now = Util.now()
		if now - state.lastRun < 4 then
			return
		end
		state.lastRun = now

		-- The lobby has the slot screen, that is the place to start from.
		if Ctx.GameUI.titleScreen() then
			if settings.AutoSelectSlot ~= false then
				Ctx.GameUI.selectSlot(settings.Slot or "B")
				task.wait(0.4)
			end
		end

		local ok
		if settings.AutoStartType == "Raids" then
			ok = AutoStart.startRaid()
		else
			ok = AutoStart.startMission()
		end

		if ok then
			state.running = true
			Ctx.Stats.session.missions = Ctx.Stats.session.missions + 1
			Util.log("auto started a", settings.AutoStartType or "Missions", "session")
		end
	end

	AutoStart.state = state

	return AutoStart
end

end)())

-- ==== Waves ===============================================
__define("Waves", (function()
--[[
	AOTR Suite :: Features / Waves
	Wave mode helpers.

	Supports
		TargetBoss             - prioritise the boss titan of the wave
		WavesUpgrades          - upgrade the gear every wave
		AutoBuyUpgradesWaves   - buy the upgrades from the wave shop
		AutoWaveDie / WaveToDieAt - end the run on a given wave
		WavesAutoSkip          - vote to skip the wave
		WavesRollBlessing      - reroll the blessing
		WavesGetCrates         - open the wave crates

	All of it is written so it keeps working during a kaitun, where the
	mission restarts constantly: the wave state is rebuilt every frame from
	the interface instead of being cached across sessions.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Waves = {}

	local state = {
		currentWave = 0,
		lastWave = 0,
		died = false,
		lastAction = 0,
	}

	------------------------------------------------------------------
	-- Wave detection
	------------------------------------------------------------------

	-- Reads the wave counter from the interface.
	Waves.currentWave = function()
		local hud = Ctx.GameUI.hud()
		if not hud then
			return state.currentWave
		end
		local label = Util.findDeep(hud, function(node)
			if not (node:IsA("TextLabel") or node:IsA("TextButton")) then
				return false
			end
			return string.find(string.lower(node.Text or ""), "wave", 1, true) ~= nil
		end, 10)
		if not label then
			return state.currentWave
		end
		local wave = label.Text:match("(%d+)")
		if wave then
			state.currentWave = tonumber(wave) or state.currentWave
		end
		return state.currentWave
	end

	------------------------------------------------------------------
	-- Buttons
	------------------------------------------------------------------

	local function clickAny(keywords)
		local root = Ctx.GameUI.interface()
		local matches = Ctx.GameUI.findClickables(root, keywords, true)
		for _, button in ipairs(matches) do
			if button.Active then
				Util.click(button)
				return true
			end
		end
		return false
	end

	------------------------------------------------------------------
	-- Actions
	------------------------------------------------------------------

	-- Votes to skip the current wave.
	Waves.skip = function()
		return clickAny({ "Skip", "Vote Skip", "Proceed" })
	end

	-- Rerolls the current blessing.
	Waves.rollBlessing = function()
		return clickAny({ "Reroll", "Roll", "Blessing" })
	end

	-- Upgrades the gear between waves.
	Waves.upgrade = function()
		return clickAny({ "Upgrade", "Upgrade Gear", "Improve" })
	end

	-- Opens the wave crates.
	Waves.getCrates = function()
		return clickAny({ "Crate", "Open Chest", "Open Crate" })
	end

	-- Buys the upgrades that are listed in the config.
	Waves.buyUpgrades = function()
		local settings = Ctx.Config.Get()
		local list = settings.WavesUpgradesToBuy
		if type(list) == "string" then
			list = { list }
		end
		if type(list) ~= "table" or #list == 0 then
			return false
		end
		local bought = false
		for _, upgrade in ipairs(list) do
			if type(upgrade) == "string" and upgrade ~= "" then
				if clickAny({ upgrade }) then
					bought = true
					task.wait(0.15)
				end
			end
		end
		return bought
	end

	------------------------------------------------------------------
	-- Dying on a wave
	------------------------------------------------------------------

	-- Ends the run on the configured wave. The character walks into a
	-- titan so the server applies the death.
	Waves.die = function()
		local player = Util.LocalPlayer
		local character = player and player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not root then
			return false
		end
		if clickAny({ "Die", "Give Up", "Surrender" }) then
			state.died = true
			return true
		end
		local titans = Ctx.Targets.getTitans()
		if #titans > 0 and titans[1].nape then
			root.CFrame = CFrame.new(titans[1].nape.Position)
			state.died = true
			return true
		end
		return false
	end

	------------------------------------------------------------------
	-- Boss targeting
	------------------------------------------------------------------

	-- When TargetBoss is on, the farm prefers the boss of the wave.
	Waves.applyTargetBoss = function()
		local settings = Ctx.Config.Get()
		if settings.TargetBoss ~= true then
			return false
		end
		if settings.TargetPriority ~= "Bosses First" then
			settings.TargetPriority = "Bosses First"
		end
		return true
	end

	------------------------------------------------------------------
	-- Main update
	------------------------------------------------------------------

	Waves.update = function()
		local settings = Ctx.Config.Get()

		if not Ctx.Safety.inMission() then
			-- A new session starts, the wave counter restarts as well.
			if state.currentWave ~= 0 then
				state.currentWave = 0
				state.lastWave = 0
				state.died = false
			end
			return
		end

		Waves.currentWave()
		Waves.applyTargetBoss()

		local now = Util.now()
		if now - state.lastAction < 0.6 then
			return
		end
		state.lastAction = now

		if settings.WavesAutoSkip == true then
			Waves.skip()
		end
		if settings.WavesRollBlessing == true then
			Waves.rollBlessing()
		end
		if settings.WavesAutoUpgrade == true then
			Waves.upgrade()
		end
		if settings.WavesBuyUpgrades == true then
			Waves.buyUpgrades()
		end
		if settings.WavesGetCrates == true then
			Waves.getCrates()
		end

		-- Auto die at a given wave.
		local dieAt = settings.WaveToDieAt or 0
		if settings.AutoWaveDie == true and dieAt > 0 and state.currentWave >= dieAt and not state.died then
			Waves.die()
		end
	end

	Waves.state = state

	return Waves
end

end)())

-- ==== ShadowBan ===============================================
__define("ShadowBan", (function()
--[[
	AOTR Suite :: Features / ShadowBan
	Detects the silent ban that Roblox applies to flagged accounts.

	Detection is based on three independent signals:
		1. player attributes that mention a ban or a restriction
		2. boolean children of the player with a matching name
		3. the server refusing to answer the read remote
]]

return function(Ctx)
	local Util = Ctx.Util
	local ShadowBan = {}

	local state = {
		lastCheck = 0,
		clean = true,
		flags = {},
	}

	local BAN_ATTRIBUTES = { "ban", "flag", "cheat", "restrict", "shadowban", "muted" }

	------------------------------------------------------------------
	-- Signals
	------------------------------------------------------------------

	local function attributeFlags()
		local flags = {}
		local player = Util.LocalPlayer
		if not player then
			return flags
		end
		for name, value in pairs(player:GetAttributes()) do
			local lower = string.lower(tostring(name))
			for _, keyword in ipairs(BAN_ATTRIBUTES) do
				if string.find(lower, keyword, 1, true) and value == true then
					table.insert(flags, tostring(name))
					break
				end
			end
		end
		return flags
	end

	local function childFlags()
		local flags = {}
		local player = Util.LocalPlayer
		if not player then
			return flags
		end
		for _, child in ipairs(player:GetDescendants()) do
			if child:IsA("BoolValue") and child.Value == true then
				local lower = string.lower(child.Name)
				for _, keyword in ipairs(BAN_ATTRIBUTES) do
					if string.find(lower, keyword, 1, true) then
						table.insert(flags, child.Name)
						break
					end
				end
			end
		end
		return flags
	end

	-- The server stops answering when the account is flagged.
	local function serverResponds()
		local remote = Ctx.Remotes.getReady()
		if not remote then
			return true
		end
		local ok = pcall(function()
			if remote:IsA("RemoteFunction") then
				remote:InvokeServer("Ping")
			else
				remote:FireServer("Ping")
			end
		end)
		return ok
	end

	------------------------------------------------------------------
	-- Check
	------------------------------------------------------------------

	ShadowBan.check = function()
		local flags = {}
		for _, flag in ipairs(attributeFlags()) do
			table.insert(flags, flag)
		end
		for _, flag in ipairs(childFlags()) do
			table.insert(flags, flag)
		end

		-- The server stops answering the read remote once the account is
		-- flagged, that is the third independent signal.
		if not serverResponds() then
			table.insert(flags, "ServerUnresponsive")
		end

		state.flags = flags
		state.clean = #flags == 0
		state.lastCheck = Util.now()
		return state.clean, flags
	end

	ShadowBan.isClean = function()
		return state.clean
	end

	ShadowBan.flags = function()
		return state.flags
	end

	-- Runs the check and stops the farm when the account is flagged.
	ShadowBan.update = function()
		local settings = Ctx.Config.Get()
		if settings.ShadowBanCheck ~= true then
			return
		end
		local now = Util.now()
		if now - state.lastCheck < 10 then
			return
		end
		local clean, flags = ShadowBan.check()
		if not clean then
			Util.warn("shadow ban detected:", table.concat(flags, ", "))
			settings.AutoFarm = false
			settings.AutoStart = false
			Ctx.Config.notifyChanged()
		end
	end

	ShadowBan.state = state

	return ShadowBan
end

end)())

-- ==== Hub ===============================================
__define("Hub", (function()
--[[
	AOTR Suite :: Hub
	The user interface.

	The UI is built on Rayfield, which is vendored in vendor/source.lua.
	Every control writes straight into the shared config table, and the
	config tab persists the changes to disk.

	When another profile is selected the controls are refreshed in place
	through the Rayfield Set methods, so the window never has to be closed
	and opened again.
]]

return function(Ctx)
	local Util = Ctx.Util
	local Hub = {}

	local Rayfield = Ctx.Rayfield
	local Config = Ctx.Config

	local window = nil
	local profileDropdown = nil
	local statsParagraph = nil
	local saveTimer = 0
	local loopsStarted = false
	local newProfileName = ""

	-- Every control that mirrors a config value, so it can be refreshed.
	local bindings = {}

	------------------------------------------------------------------
	-- Helpers
	------------------------------------------------------------------

	local function settings()
		return Config.Get()
	end

	local function notify(title, content, duration)
		Rayfield:Notify({
			Title = title,
			Content = content,
			Duration = duration or 4,
		})
	end

	-- Schedules a save a moment after the last change, so dragging a
	-- slider does not write a hundred files.
	local function scheduleSave()
		saveTimer = Util.now()
	end

	local function register(element, name, kind, extra)
		table.insert(bindings, {
			element = element,
			name = name,
			kind = kind,
			extra = extra,
		})
		return element
	end

	local function createToggle(tab, name, default)
		local current = settings()[name]
		if current == nil then
			current = default or false
		end
		local element = tab:CreateToggle({
			Name = name,
			CurrentValue = current == true,
			Flag = "AOTR_" .. name,
			Callback = function(value)
				Config.Set(name, value == true)
				scheduleSave()
			end,
		})
		return register(element, name, "toggle")
	end

	local function createDropdown(tab, name, options, default)
		local current = settings()[name]
		if current == nil then
			current = default or options[1]
		end
		local element = tab:CreateDropdown({
			Name = name,
			Options = options,
			CurrentOption = { current },
			MultipleOptions = false,
			Flag = "AOTR_" .. name,
			Callback = function(option)
				local value = type(option) == "table" and option[1] or option
				Config.Set(name, value)
				scheduleSave()
			end,
		})
		return register(element, name, "dropdown")
	end

	local function createSlider(tab, name, range, increment, suffix, default)
		local current = settings()[name]
		if type(current) ~= "number" then
			current = default or range[1]
		end
		local element = tab:CreateSlider({
			Name = name,
			Range = range,
			Increment = increment,
			Suffix = suffix,
			CurrentValue = current,
			Flag = "AOTR_" .. name,
			Callback = function(value)
				Config.Set(name, value)
				scheduleSave()
			end,
		})
		return register(element, name, "slider", { min = range[1], max = range[2] })
	end

	local function createInput(tab, name, placeholder, default)
		local current = settings()[name]
		if type(current) ~= "string" then
			current = default or ""
		end
		local element = tab:CreateInput({
			Name = name,
			CurrentValue = current,
			PlaceholderText = placeholder,
			RemoveTextAfterFocusLost = false,
			Flag = "AOTR_" .. name,
			Callback = function(text)
				Config.Set(name, tostring(text or ""))
				scheduleSave()
			end,
		})
		return register(element, name, "input")
	end

	-- A list of strings that is edited as one comma separated line.
	local function createListInput(tab, name, placeholder)
		local current = settings()[name]
		if type(current) ~= "table" then
			current = {}
		end
		local element = tab:CreateInput({
			Name = name,
			CurrentValue = table.concat(current, ", "),
			PlaceholderText = placeholder,
			RemoveTextAfterFocusLost = false,
			Flag = "AOTR_" .. name,
			Callback = function(text)
				local list = {}
				for piece in string.gmatch(tostring(text or ""), "([^,]+)") do
					local trimmed = piece:match("^%s*(.-)%s*$")
					if trimmed ~= "" then
						table.insert(list, trimmed)
					end
				end
				Config.Set(name, list)
				scheduleSave()
			end,
		})
		return register(element, name, "list")
	end

	------------------------------------------------------------------
	-- Refresh
	------------------------------------------------------------------

	-- Pushes the values of the active profile back into the controls.
	Hub.refresh = function()
		local current = settings()
		for _, binding in ipairs(bindings) do
			local value = current[binding.name]
			pcall(function()
				if binding.kind == "toggle" then
					binding.element:Set(value == true)
				elseif binding.kind == "slider" then
					if type(value) == "number" then
						local minimum = binding.extra and binding.extra.min or value
						local maximum = binding.extra and binding.extra.max or value
						binding.element:Set(Util.clamp(value, minimum, maximum))
					end
				elseif binding.kind == "input" then
					binding.element:Set(tostring(value or ""))
				elseif binding.kind == "list" then
					if type(value) == "table" then
						binding.element:Set(table.concat(value, ", "))
					end
				elseif binding.kind == "dropdown" then
					if type(value) == "string" then
						binding.element:Set({ value })
					end
				end
			end)
		end
	end

	------------------------------------------------------------------
	-- Build
	------------------------------------------------------------------

	Hub.build = function()
		window = Rayfield:CreateWindow({
			Name = "AOTR Suite | Attack on Titan: Revolution",
			LoadingTitle = "AOTR Suite",
			LoadingSubtitle = "Attack on Titan: Revolution",
			ConfigurationSaving = {
				Enabled = false,
			},
			KeySystem = false,
		})

		--------------------------------------------------------------
		-- Tab: Auto Farm
		--------------------------------------------------------------
		local farm = window:CreateTab("Auto Farm", 0)
		farm:CreateSection("Farming")

		createToggle(farm, "AutoFarm", false)
		createDropdown(farm, "FarmMethod", { "Blade", "Hover", "Teleport" }, "Blade")
		createDropdown(farm, "TargetPriority", { "Closest", "Bosses First", "Crawlers & Abnormals", "Lowest HP" }, "Closest")
		createToggle(farm, "DisableHovering", false)
		createToggle(farm, "TeleportTitans", false)
		createSlider(farm, "HoverHeight", { 0, 600 }, 5, " studs", 265)
		createSlider(farm, "HoverSpeed", { 500, 8000 }, 100, "", 3000)
		createSlider(farm, "BehindNapeDistance", { 0, 20 }, 0.5, " studs", 2)
		createSlider(farm, "HitDistance", { 50, 2000 }, 50, " studs", 1000)

		farm:CreateSection("Combat")
		createSlider(farm, "MultiHit", { 1, 10 }, 1, " targets", 9)
		createSlider(farm, "BossDamage", { 0, 20 }, 1, " hits", 9)
		createToggle(farm, "DamageExtender", false)
		createSlider(farm, "DamageMultiplier", { 1, 50 }, 1, "x", 3)
		createToggle(farm, "InfiniteSpears", false)
		createToggle(farm, "AutoUseSkills", false)

		farm:CreateSection("Visuals")
		createToggle(farm, "TitanEsp", false)
		createToggle(farm, "NapeExtend", false)
		createToggle(farm, "NoTitanLag", true)
		createToggle(farm, "DisableRendering", true)

		--------------------------------------------------------------
		-- Tab: Reload & Refill
		--------------------------------------------------------------
		local reload = window:CreateTab("Reload & Refill", 0)
		reload:CreateSection("Reload")
		createToggle(reload, "AutoReload", false)
		createDropdown(reload, "ReloadStation", { "Safest", "Nearest" }, "Safest")
		createToggle(reload, "AutoRefill", false)

		reload:CreateSection("Safety")
		local safetyValue = settings().SafetyTime
		if type(safetyValue) ~= "number" then
			safetyValue = 30
		end
		local safetySlider = reload:CreateSlider({
			Name = "Safety Time",
			Range = { 30, 600 },
			Increment = 5,
			Suffix = " s",
			CurrentValue = math.max(30, safetyValue),
			Flag = "AOTR_SafetyTime",
			Callback = function(value)
				-- The mission timer never goes below 30 seconds.
				Config.Set("SafetyTime", math.max(30, value))
				scheduleSave()
			end,
		})
		register(safetySlider, "SafetyTime", "slider", { min = 30, max = 600 })

		reload:CreateParagraph({
			Name = "Minimum mission timer is 30 seconds.",
			Content = "The suite leaves a mission only after the real mission timer passed the value above.",
		})

		--------------------------------------------------------------
		-- Tab: Rewards
		--------------------------------------------------------------
		local rewards = window:CreateTab("Rewards", 0)
		rewards:CreateSection("Auto claim")
		createToggle(rewards, "ClaimAchievements", false)
		createToggle(rewards, "ClaimQuests", false)
		createToggle(rewards, "ClaimBattlePass", true)
		rewards:CreateParagraph({
			Name = "Auto Claim Daily Reward",
			Content = "Always active. There is no toggle for it.",
		})

		rewards:CreateSection("Boosts")
		createToggle(rewards, "BuyBoosts", false)
		createDropdown(rewards, "ItemtoBuyWith", Config.CURRENCIES, "Canes")
		createListInput(rewards, "Boosts", "2x Gold Boost [2h], 2x XP Boost [1h]")

		--------------------------------------------------------------
		-- Tab: Auto Start
		--------------------------------------------------------------
		local autoStart = window:CreateTab("Auto Start", 0)
		autoStart:CreateSection("Session")
		createToggle(autoStart, "AutoStart", false)
		createDropdown(autoStart, "AutoStartType", { "Missions", "Raids" }, "Missions")
		createDropdown(autoStart, "AutoStartMap", {
			"Shiganshina",
			"Trost",
			"Outskirts",
			"Giant Forest",
			"Utgard",
			"Docks",
			"Stohess",
			"Chapel",
		}, "Shiganshina")
		createDropdown(autoStart, "AutoStartObjective", { "Breach", "Skirmish", "Protect", "Clear" }, "Breach")

		local difficultyNames = {}
		for _, entry in ipairs(Config.DIFFICULTIES) do
			table.insert(difficultyNames, entry.name)
		end
		createDropdown(autoStart, "AutoStartDifficulty", difficultyNames, "Hardest (w/ Freedom)")

		autoStart:CreateSection("Modifiers")
		createListInput(autoStart, "AutoStartModifiers", "Nightmare, Oddball, Fog")
		createToggle(autoStart, "PlayBoostedMap", false)

		autoStart:CreateSection("Loop")
		createToggle(autoStart, "Kaitun", false)
		createToggle(autoStart, "AutoReturn", false)
		createSlider(autoStart, "ReturnAmount", { 1, 100 }, 1, " missions", 15)
		autoStart:CreateParagraph({
			Name = "Kaitun",
			Content = "Restarts a session right after the previous one ended. Wave features and the boost currency keep working inside a kaitun.",
		})

		--------------------------------------------------------------
		-- Tab: Waves
		--------------------------------------------------------------
		local waves = window:CreateTab("Waves", 0)
		waves:CreateSection("Wave mode")
		createToggle(waves, "TargetBoss", false)
		createToggle(waves, "WavesAutoSkip", false)
		createToggle(waves, "WavesRollBlessing", false)
		createToggle(waves, "WavesAutoUpgrade", false)
		createToggle(waves, "WavesBuyUpgrades", false)
		createToggle(waves, "WavesGetCrates", false)

		waves:CreateSection("End the run")
		createToggle(waves, "AutoWaveDie", false)
		createSlider(waves, "WaveToDieAt", { 0, 100 }, 1, "", 0)
		createListInput(waves, "WavesUpgradesToBuy", "Damage, Speed")

		--------------------------------------------------------------
		-- Tab: Progression
		--------------------------------------------------------------
		local progression = window:CreateTab("Progression", 0)
		progression:CreateSection("Prestige")
		createToggle(progression, "AutoPrestige", false)
		createSlider(progression, "PrestigeToStopAt", { 1, 50 }, 1, "", 5)

		progression:CreateSection("Skill tree")
		createToggle(progression, "AutoSkillTree", false)
		createDropdown(progression, "LeftPath", { "Skill Cooldown", "Damage", "Damage Reduction", "Health" }, "Skill Cooldown")
		createDropdown(progression, "MiddlePath", { "Skill Cooldown", "Damage", "Damage Reduction", "Health" }, "Damage")
		createDropdown(progression, "RightPath", { "Skill Cooldown", "Damage", "Damage Reduction", "Health" }, "Damage Reduction")
		createDropdown(progression, "PathPriority", { "Left", "Middle", "Right" }, "Middle")

		--------------------------------------------------------------
		-- Tab: Webhook
		--------------------------------------------------------------
		local webhook = window:CreateTab("Webhook & Stats", 0)
		webhook:CreateSection("Discord webhook")
		createToggle(webhook, "Webhook", false)
		createInput(webhook, "WebhookLink", "https://discord.com/api/webhooks/...", "")
		createToggle(webhook, "ShowUsername", true)
		createToggle(webhook, "SendSafetyUpdate", false)
		webhook:CreateButton({
			Name = "Send test webhook",
			Callback = function()
				if Ctx.Webhook.test() then
					notify("Webhook", "The test message was sent.")
				else
					notify("Webhook", "The message could not be sent, check the URL.", 5)
				end
			end,
		})

		webhook:CreateSection("Live stats")
		statsParagraph = webhook:CreateParagraph({
			Name = "Player Stats",
			Content = "waiting for data",
		})
		local function refreshStats()
			local snapshot = Ctx.Stats.snapshot()
			local lines = {}
			for _, entry in ipairs(Ctx.Stats.CURRENCIES) do
				local value = snapshot[entry.key]
				if type(value) == "number" then
					table.insert(lines, string.format("%s: %s", entry.label, Util.formatNumber(value)))
				end
			end
			table.insert(lines, "")
			table.insert(lines, string.format("Missions: %d", snapshot.session.missions))
			table.insert(lines, string.format("Raids: %d", snapshot.session.raids))
			table.insert(lines, string.format("Waves: %d", snapshot.session.waves))
			table.insert(lines, string.format("Titans killed: %d", snapshot.session.titansKilled))
			table.insert(lines, string.format("Reloads: %d", snapshot.session.bladesReloaded))
			table.insert(lines, string.format("Session: %s", Util.formatDuration(snapshot.sessionSeconds)))
			pcall(function()
				statsParagraph:Set({
					Title = "Player Stats",
					Content = table.concat(lines, "\n"),
				})
			end)
		end

		--------------------------------------------------------------
		-- Tab: Config
		--------------------------------------------------------------
		local configTab = window:CreateTab("Config", 0)
		configTab:CreateSection("Profile")

		local function profileNames()
			local names = {}
			for _, profile in ipairs(Config.listProfiles()) do
				table.insert(names, profile.name)
			end
			if #names == 0 then
				table.insert(names, Config.DEFAULT_PROFILE)
			end
			return names
		end

		profileDropdown = configTab:CreateDropdown({
			Name = "Config Profile",
			Options = profileNames(),
			CurrentOption = { Config.ActiveProfile },
			MultipleOptions = false,
			Flag = "AOTR_ConfigProfile",
			Callback = function(option)
				local name = type(option) == "table" and option[1] or option
				if name and name ~= Config.ActiveProfile then
					Config.Select(name)
					notify("Config", "Loaded profile: " .. name)
					-- The controls read from the config table, so they are
					-- refreshed to show the values of the new profile.
					Hub.refresh()
				end
			end,
		})

		configTab:CreateInput({
			Name = "New profile name",
			CurrentValue = "",
			PlaceholderText = "my farm config",
			RemoveTextAfterFocusLost = false,
			Flag = "AOTR_NewProfileName",
			Callback = function(text)
				newProfileName = tostring(text or "")
			end,
		})

		configTab:CreateButton({
			Name = "Create profile",
			Callback = function()
				local name = Util.sanitizeName(newProfileName)
				if name == "" or name == "default" then
					notify("Config", "Enter a name for the new profile.")
					return
				end
				Config.New(name)
				newProfileName = ""
				notify("Config", "Created profile: " .. name)
				profileDropdown:Refresh(profileNames())
			end,
		})

		configTab:CreateButton({
			Name = "Save config now",
			Callback = function()
				if Config.Save() then
					notify("Config", "Saved to " .. Config.profilePath(Config.ActiveProfile))
				else
					notify("Config", "The config could not be saved.", 5)
				end
			end,
		})

		configTab:CreateButton({
			Name = "Reload config from disk",
			Callback = function()
				if Config.loadProfile(Config.ActiveProfile) then
					notify("Config", "Reloaded profile: " .. Config.ActiveProfile)
					Hub.refresh()
				else
					notify("Config", "No file found for this profile.", 4)
				end
			end,
		})

		configTab:CreateButton({
			Name = "Delete profile",
			Callback = function()
				local name = Config.ActiveProfile
				Config.Delete(name)
				notify("Config", "Deleted profile: " .. name)
				profileDropdown:Refresh(profileNames())
				Hub.refresh()
			end,
		})

		configTab:CreateParagraph({
			Name = "Config folder",
			Content = Config.CONFIG_FOLDER,
		})

		--------------------------------------------------------------
		-- Tab: Misc
		--------------------------------------------------------------
		local misc = window:CreateTab("Misc", 0)
		misc:CreateSection("General")
		createToggle(misc, "AntiAFK", true)
		createToggle(misc, "ShadowBanCheck", false)
		misc:CreateButton({
			Name = "Check shadow ban now",
			Callback = function()
				local clean, flags = Ctx.ShadowBan.check()
				if clean then
					notify("Shadow ban", "No restriction flags were found.")
				else
					notify("Shadow ban", "Flags found: " .. table.concat(flags, ", "), 7)
				end
			end,
		})

		misc:CreateSection("Server")
		createInput(misc, "PrivateServerCode", "-", "-")
		createToggle(misc, "LeaveIfMorePlayers", false)
		createToggle(misc, "AutoSelectSlot", true)
		createDropdown(misc, "Slot", { "A", "B", "C", "D" }, "B")

		misc:CreateSection("Streak")
		createSlider(misc, "StreakAmount", { 0, 1000000 }, 1000, "", 0)
		createToggle(misc, "StreakDie", false)

		------------------------------------------------------------------
		-- Auto save and live stats
		------------------------------------------------------------------
		Config.onChanged(function()
			scheduleSave()
		end)

		if not loopsStarted then
			loopsStarted = true

			-- The config is written a moment after the last change, so
			-- dragging a slider does not write a hundred files.
			task.spawn(function()
				while true do
					task.wait(1)
					if saveTimer > 0 and Util.now() - saveTimer > 1.5 then
						saveTimer = 0
						Config.Save()
					end
				end
			end)

			task.spawn(function()
				while true do
					task.wait(2)
					pcall(refreshStats)
				end
			end)
		end

		return window
	end

	Hub.window = function()
		return window
	end

	Hub.notify = notify

	return Hub
end

end)())

-- ==== main ===============================================
__define("main", (function()
--[[
	AOTR Suite :: main
	Entry point. Builds the context, boots the interface and starts the
	feature loops.
]]

return function(MOD)
	local Util = MOD.Util
	local RunService = game:GetService("RunService")
	local Players = game:GetService("Players")

	------------------------------------------------------------------
	-- Single instance guard
	------------------------------------------------------------------

	local genv = (getgenv and getgenv()) or _G
	if genv.AOTRSuite and genv.AOTRSuite.Running then
		Util.warn("AOTRSuite is already running.")
		return nil
	end

	------------------------------------------------------------------
	-- Context
	------------------------------------------------------------------
	-- The context is filled in step by step. Every module receives the
	-- same table by reference and only reads from it at runtime, so the
	-- order below does not have to be perfect.

	local Ctx = {
		Util = Util,
		Rayfield = MOD.Rayfield,
		state = {},
	}

	if type(MOD.Rayfield) ~= "table" then
		Util.warn("the interface library failed to load, the suite cannot start")
		return nil
	end

	local function build(name)
		Ctx[name] = MOD[name](Ctx)
		return Ctx[name]
	end

	build("Config")
	build("Remotes")
	build("GameUI")
	build("Targets")
	build("Stats")
	build("Safety")
	build("Webhook")
	build("Farm")
	build("Combat")
	build("Reload")
	build("Claim")
	build("Boosts")
	build("AutoStart")
	build("Waves")
	build("ShadowBan")
	build("Hub")

	local Config = Ctx.Config
	local GameUI = Ctx.GameUI
	local Stats = Ctx.Stats
	local Safety = Ctx.Safety
	local Webhook = Ctx.Webhook
	local Farm = Ctx.Farm
	local Combat = Ctx.Combat
	local Reload = Ctx.Reload
	local Claim = Ctx.Claim
	local Boosts = Ctx.Boosts
	local AutoStart = Ctx.AutoStart
	local Waves = Ctx.Waves
	local ShadowBan = Ctx.ShadowBan
	local Hub = Ctx.Hub

	------------------------------------------------------------------
	-- Boot
	------------------------------------------------------------------

	Config.AutoLoad()
	Ctx.Remotes.resolve(true)

	Hub.build()

	------------------------------------------------------------------
	-- Anti AFK
	------------------------------------------------------------------

	local antiAfkConnection = nil
	local function setupAntiAfK()
		if antiAfkConnection then
			antiAfkConnection:Disconnect()
			antiAfkConnection = nil
		end
		if not Config.Get().AntiAFK then
			return
		end
		local player = Players.LocalPlayer
		if not player then
			return
		end
		antiAfkConnection = player.Idled:Connect(function()
			Util.warn("idle detected, nudging the character")
			local character = player.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root then
				root.CFrame = root.CFrame + Vector3.new(0, 0, 0.5)
			end
		end)
	end
	setupAntiAfK()
	Config.onChanged(setupAntiAfK)

	------------------------------------------------------------------
	-- Session bookkeeping
	------------------------------------------------------------------

	local lastRewardsVisible = false
	local lastInMission = false
	local missionsSinceReturn = 0

	local function handleMissionEnd()
		local drops = Webhook.collectDrops()
		if Config.Get().Webhook and Config.Get().SendSafetyUpdate then
			Webhook.reportMission(drops)
		end
		Stats.session.missions = Stats.session.missions + 1
		missionsSinceReturn = missionsSinceReturn + 1
		Webhook.markBaseline()

		local settings = Config.Get()
		if settings.AutoReturn == true and missionsSinceReturn >= (settings.ReturnAmount or 15) then
			missionsSinceReturn = 0
			local leave = GameUI.leaveButton()
			if leave then
				Util.click(leave)
			end
		end
	end

	------------------------------------------------------------------
	-- Loops
	------------------------------------------------------------------

	-- Fast loop: movement, targeting and the safety timer.
	RunService.Heartbeat:Connect(function(deltaTime)
		local ok, err = pcall(function()
			Safety.update()
			Farm.update(deltaTime)
			Combat.update()
		end)
		if not ok then
			Util.warn("heartbeat:", err)
		end
	end)

	-- Slow loop: everything that talks to the interface.
	task.spawn(function()
		while true do
			task.wait(1)
			pcall(Reload.update)
			pcall(Claim.update)
			pcall(Waves.update)
			pcall(ShadowBan.update)

			-- Mission end detection.
			local rewardsVisible = GameUI.rewardsVisible()
			if rewardsVisible and not lastRewardsVisible then
				handleMissionEnd()
			end
			lastRewardsVisible = rewardsVisible

			-- The drop list is the difference between the currencies at the
			-- start and at the end of the mission, so the baseline is taken
			-- when the mission starts.
			local inMission = Safety.inMission()
			if inMission and not lastInMission then
				Webhook.markBaseline()
			end
			lastInMission = inMission
		end
	end)

	-- Slower loop: the shop and the session automation.
	task.spawn(function()
		while true do
			task.wait(3)
			pcall(Boosts.update)
			pcall(AutoStart.update)
		end
	end)

	-- The nape extender runs a bit slower than the combat loop.
	task.spawn(function()
		while true do
			task.wait(0.5)
			pcall(Farm.extendNapes)
		end
	end)

	------------------------------------------------------------------
	-- Public handle
	------------------------------------------------------------------

	genv.AOTRSuite = {
		Running = true,
		Config = Config,
		Ctx = Ctx,
		Stop = function()
			RunService.Heartbeat:Disconnect()
			if antiAfkConnection then
				antiAfkConnection:Disconnect()
			end
			local window = Hub.window()
			if window then
				window:Destroy()
			end
			genv.AOTRSuite.Running = false
		end,
	}

	Util.log("AOTR Suite ready")
	return genv.AOTRSuite
end

end)())

-- ==== boot ==================================================
__MOD["main"](__MOD)
